/// Status filter for the ECS Tasks sub-tab (the list shows running + recently
/// stopped tasks; this narrows to one or the other). Toggled with `f`.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum EcsTaskStatusFilter {
    All,
    Running,
    Stopped}

impl EcsTaskStatusFilter {
    /// Cycle All → Running → Stopped → All.
    pub fn next(self) -> Self {
        match self {
            EcsTaskStatusFilter::All => EcsTaskStatusFilter::Running,
            EcsTaskStatusFilter::Running => EcsTaskStatusFilter::Stopped,
            EcsTaskStatusFilter::Stopped => EcsTaskStatusFilter::All}
    }

    pub fn label(self) -> &'static str {
        match self {
            EcsTaskStatusFilter::All => "all",
            EcsTaskStatusFilter::Running => "running",
            EcsTaskStatusFilter::Stopped => "stopped"}
    }
}

/// Generic list sort, cycled with `z`. `Default` keeps the service's load
/// order — several services curate it (Cost by spend, stopped ECS tasks
/// newest-first, ECR images by push date), so it's always the first stop.
/// Only applied when no fuzzy query text is active: match-score order wins
/// while searching. Reset on service switch.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub enum ListSort {
    #[default]
    Default,
    NameAsc,
    NameDesc,
    State}

impl ListSort {
    /// Cycle Default → name ↑ → name ↓ → state → Default.
    pub fn next(self) -> Self {
        match self {
            ListSort::Default => ListSort::NameAsc,
            ListSort::NameAsc => ListSort::NameDesc,
            ListSort::NameDesc => ListSort::State,
            ListSort::State => ListSort::Default}
    }

    /// Corner-chip label; `None` when inactive (default order).
    pub fn label(self) -> Option<&'static str> {
        match self {
            ListSort::Default => None,
            ListSort::NameAsc => Some("name ↑"),
            ListSort::NameDesc => Some("name ↓"),
            ListSort::State => Some("state")}
    }
}

/// Severity rank for `ListSort::State` — problem states surface first, the
/// sort is stable so the service's curated order survives within each rank.
fn state_sort_rank(state: &crate::aws::resource::ResourceState) -> u8 {
    use crate::aws::resource::ResourceState::*;
    match state {
        Unavailable => 0,
        Terminated => 1,
        Stopped => 2,
        Deleting => 3,
        Pending => 4,
        Creating => 5,
        Unknown(_) => 6,
        Running => 7,
        Available => 8}
}

/// Epoch-millis an execution row started, for the newest-first default order on
/// an Executions sub-tab. Anything that isn't an execution sorts last, so a
/// stray row can never displace the newest run.
fn execution_start_ms(r: &dyn crate::aws::resource::Resource) -> i64 {
    let any = r.as_any();
    if let Some(e) = any.downcast_ref::<crate::aws::services::code::CodePipelineExecution>() {
        return e.start_ms;
    }
    if let Some(e) = any.downcast_ref::<crate::aws::services::step_functions::SfnExecution>() {
        return e.started_secs.saturating_mul(1000);
    }
    if let Some(p) = any.downcast_ref::<crate::aws::services::code::CodeCommitPullRequest>() {
        return p.created_ms;
    }
    i64::MIN
}

