/// `f` filter on an Executions sub-tab (Step Functions, CodePipeline).
/// Succeeded executions dominate a healthy account, so being able to keep only
/// the in-flight or only the broken ones is the point of those tabs.
#[derive(Debug, Clone, Copy, PartialEq)]
pub enum ExecStatusFilter {
    All,
    Running,
    Failed,
}

impl ExecStatusFilter {
    pub fn next(self) -> Self {
        match self {
            ExecStatusFilter::All => ExecStatusFilter::Running,
            ExecStatusFilter::Running => ExecStatusFilter::Failed,
            ExecStatusFilter::Failed => ExecStatusFilter::All,
        }
    }

    pub fn label(self) -> &'static str {
        match self {
            ExecStatusFilter::All => "all",
            ExecStatusFilter::Running => "running",
            ExecStatusFilter::Failed => "failed",
        }
    }
}

