/// Destination sub-tab for a "go to resource" jump (`Enter` same-service /
/// `gd` cross-service). Each variant carries the concrete view enum so the
/// jump executor can set the right `*_view` field on `App`.
#[derive(Debug, Clone, serde::Serialize, serde::Deserialize)]
pub enum JumpView {
    Ec2(Ec2View),
    Vpc(VpcView),
    Iam(IamView),
    Cfn(CfnView),
    Rds(RdsView),
    Ecs(EcsView),
    Elb(ElbView),
    Msg(MsgView),
    Cw(CwView),
    Secrets,
    Ssm(SsmView),
    R53(R53View),
    Nfw(NfwView),
    Code(CodeView),
    Ic(IcView),
    Org(OrgView),
    Resolver(ResolverView),
    Inspector(InspectorView),
    Eb(EventBridgeView),
    Dx(DxView),
    Tgw(TgwView),
    ApiGw(ApiGatewayView),
    Cf(CloudFrontView),
    Sfn(SfnView),
    Sh(SecurityHubView),
    AgentCore(AgentCoreView),
    /// WAF carries both the sub-tab and the scope (CLOUDFRONT vs REGIONAL) — a
    /// CloudFront distribution's Web ACL is always CLOUDFRONT scope, which lives
    /// in a separate (us-east-1) variant of the WAF list.
    Waf(WafView, WafScope),
    /// Single-view services (S3, Lambda, ACM, ASG): switch service + search,
    /// no sub-tab to set.
    None}

/// A resolved jump destination: which service, which sub-tab, and the id to
/// search/select once there.
#[derive(Debug, Clone)]
pub struct JumpTarget {
    pub service: ServiceType,
    pub view: JumpView,
    pub id: String}

/// A captured navigation location for the "go back" / jump-list history. Holds
/// everything needed to land you back where you were (list-row depth): the
/// service + sub-tab, your search query, and the selected resource's id.
#[derive(Debug, Clone, serde::Serialize, serde::Deserialize)]
pub struct NavLocation {
    pub service: ServiceType,
    pub view: JumpView,
    pub query: String,
    pub selected_id: Option<String>,
    /// Precomputed one-line label for the jump-list picker.
    pub label: String,
    /// For S3 object bookmarks: `bucket/key` path to open in the object browser.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub s3_object_path: Option<(String, String)>,
    /// Captured while the detail pane was focused — restoring re-enters the
    /// detail pane once the row resolves.
    #[serde(default)]
    pub details_focused: bool,
    /// The active split-pane section name at capture time (walk!-snapshot
    /// order) — restored by cycling from the default section. Name-keyed so
    /// stale bookmarks survive a pane reshuffle (unknown name = default).
    #[serde(default)]
    pub detail_section: Option<String>}

/// Cap on the navigation timeline length (oldest entries drop off the front).
const NAV_HISTORY_MAX: usize = 25;

/// Severity of a recorded status message (drives the icon/colour in the
/// `M` message-history viewer).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum MessageLevel {
    Success,
    Error}

/// A load-phase failure that means "the endpoint doesn't implement this
/// operation" rather than "something is wrong with the account". Only
/// consulted while a custom endpoint (floci / LocalStack) is active — real
/// AWS never returns these for a read call neboto is entitled to make.
pub(crate) fn is_emulator_unsupported_warning(warning: &str) -> bool {
    let w = warning.to_ascii_lowercase();
    [
        "unsupportedoperation",
        "notimplemented",
        "not implemented",
        "unknownoperation",
        "invalidaction",
        "not supported",
        "unsupported",
        "501",
    ]
    .iter()
    .any(|needle| w.contains(needle))
}

#[cfg(test)]
mod emulator_warning_tests {
    use super::is_emulator_unsupported_warning;

    #[test]
    fn unsupported_operation_from_an_emulator_is_recognised() {
        assert!(is_emulator_unsupported_warning(
            "snapshots: UnsupportedOperation: DescribeSnapshots is not supported"
        ));
        assert!(is_emulator_unsupported_warning("images: NotImplemented"));
        assert!(is_emulator_unsupported_warning("addresses: HTTP 501"));
    }

    #[test]
    fn real_failures_are_not_swallowed() {
        assert!(!is_emulator_unsupported_warning(
            "snapshots: UnauthorizedOperation: You are not authorized to perform this operation"
        ));
        assert!(!is_emulator_unsupported_warning("volumes: RequestLimitExceeded"));
        assert!(!is_emulator_unsupported_warning("images: timed out"));
    }
}

/// One entry in the reviewable message history (`M`). Time is kept as an
/// `Instant` and rendered relatively ("3m ago") — no wall-clock dependency.
#[derive(Debug, Clone)]
pub struct MessageEntry {
    pub level: MessageLevel,
    pub text: String,
    pub at: Instant}

/// Cap on the message history length (oldest entries drop off the back).
const MESSAGE_HISTORY_MAX: usize = 100;

/// A deep export (`X` over a list visual selection) armed by the keypress and
/// completed by `App::deep_export_tick` once the lazy detail sections it fired
/// have landed. Rows are held **by id**: the wait spans main-loop iterations,
/// and the positional visual selection does not survive a list rebuild.
#[derive(Debug, Clone)]
pub struct PendingDeepExport {
    /// Ids of the selected resources, in display order at arm time.
    pub ids: Vec<String>,
    /// When `X` was pressed — the wait-limit clock.
    pub started: Instant,
}

/// Watch-mode (auto-refresh) state. The "is a refresh due" decision lives here,
/// off `App`, so it unit-tests without AWS clients. Every reason to hold off
/// (load in flight, overlay open, search active, region switching) is folded
/// into the caller-supplied `blocked` flag.
#[derive(Debug, Clone)]
pub struct WatchState {
    pub enabled: bool,
    pub interval: Duration,
    /// When the last auto- or manual-triggered watch refresh started. `None`
    /// means "refresh at the first opportunity" (set on toggle-on, so `w`
    /// feels immediate).
    pub last_refresh: Option<Instant>}

/// `+`/`-` step through these interval presets (seconds).
const WATCH_INTERVALS: &[u64] = &[5, 10, 15, 30, 60, 120, 300];

impl WatchState {
    pub const DEFAULT_SECS: u64 = 10;

    pub fn new(enabled: bool, interval_secs: Option<u64>) -> Self {
        let secs = interval_secs
            .unwrap_or(Self::DEFAULT_SECS)
            .clamp(WATCH_INTERVALS[0], *WATCH_INTERVALS.last().unwrap());
        Self {
            enabled,
            interval: Duration::from_secs(secs),
            last_refresh: None}
    }

    /// Whether an auto-refresh should fire now.
    pub fn due(&self, blocked: bool) -> bool {
        if !self.enabled || blocked {
            return false;
        }
        match self.last_refresh {
            None => true,
            Some(t) => t.elapsed() >= self.interval}
    }

    pub fn mark_refreshed(&mut self) {
        self.last_refresh = Some(Instant::now());
    }

    /// Next preset above the current interval (`+`). A config value between
    /// presets moves to the nearest preset in that direction.
    pub fn lengthen(&mut self) {
        let cur = self.interval.as_secs();
        if let Some(&next) = WATCH_INTERVALS.iter().find(|&&s| s > cur) {
            self.interval = Duration::from_secs(next);
        }
    }

    /// Previous preset below the current interval (`-`).
    pub fn shorten(&mut self) {
        let cur = self.interval.as_secs();
        if let Some(&prev) = WATCH_INTERVALS.iter().rev().find(|&&s| s < cur) {
            self.interval = Duration::from_secs(prev);
        }
    }
}

/// Half-page step for `Ctrl-d` / `Ctrl-u` in the detail pane (matches the
/// list pane's `PgUp`/`PgDn` jump of 10 rows).
const DETAIL_PAGE_STEP: usize = 10;

/// Cap on alarms the timeline lens fetches history for — one
/// `DescribeAlarmHistory` call each, and past a handful the merged view
/// stops being readable anyway.
const MAX_TIMELINE_ALARMS: usize = 5;
/// Route 53 Records sub-tab budgets (see `trigger_r53_all_records_load`):
/// zones with more records than this are skipped by the cross-zone list…
const MAX_R53_TAB_ZONE_RECORDS: i64 = 3_000;
/// …and so are zones beyond this many per trigger.
const MAX_R53_TAB_ZONES: usize = 100;

/// Zero-fetch inputs for the change timeline (`W`), computed by
/// `App::timeline_inputs` from the selected resource before the async
/// sources are fired.
#[derive(Default)]
struct TimelineInputs {
    ownership_line: Option<String>,
    /// Owning CFN stack (from the ownership tags) — names the CFN source.
    stack: Option<String>,
    logical_id: Option<String>,
    /// Alarms matched from the warm CloudWatch cache.
    alarm_names: Vec<String>,
    cw_cache_warm: bool,
    /// ECS deployment + service-event rows, straight off the struct.
    deploy_rows: Vec<crate::timeline::TimelineRow>,
}

/// Where `Ctrl-O` should move the jump-list cursor, given the timeline length
/// and the current cursor. `None` cursor = "live" (newest, past the end). The
/// step is non-destructive — entries are never removed by going back.
///
/// Returns the new cursor index, or `None` when there's nowhere further back
/// (empty timeline, or already parked on the oldest entry).
fn nav_back_target(len: usize, cursor: Option<usize>) -> Option<usize> {
    match cursor {
        None => len.checked_sub(1), // live → newest entry
        Some(0) => None,            // already at the oldest
        Some(i) => Some(i - 1)}
}

/// Structural side of recording a navigation location (shared with
/// `record_location`, kept pure for testing): when parked mid-history, drop the
/// stale forward branch; when live, append `loc` unless it duplicates the top.
/// Caps the timeline and returns the cursor to "live".
fn record_into<T>(
    history: &mut Vec<T>,
    cursor: &mut Option<usize>,
    loc: T,
    is_dup_top: bool,
    cap: usize,
) {
    match *cursor {
        Some(i) => history.truncate(i + 1),
        None => {
            if !is_dup_top {
                history.push(loc);
            }
        }
    }
    let overflow = history.len().saturating_sub(cap);
    if overflow > 0 {
        history.drain(0..overflow);
    }
    *cursor = None;
}


