/// Compact status-message form for a set of export paths that share a stem:
/// `neboto-ec2-20260619-120000.{json, csv, md}`.
fn format_export_paths(paths: &[std::path::PathBuf]) -> String {
    let stem = paths
        .first()
        .and_then(|p| p.file_stem().and_then(|s| s.to_str()))
        .unwrap_or("export");
    let exts: Vec<&str> = paths
        .iter()
        .filter_map(|p| p.extension().and_then(|e| e.to_str()))
        .collect();
    if exts.is_empty() {
        stem.to_string()
    } else {
        format!("{}.{{{}}}", stem, exts.join(", "))
    }
}

