    fn trigger_r53_health_metrics_load(&mut self, event_tx: &mpsc::UnboundedSender<Event>) {
        if let Some(id) = self.selected_r53_health_check_id() {
            let time_range = self.r53_health_metrics_time_range;
            self.r53_health_metrics
                .insert(id.clone(), R53HealthMetricsState::Loading);
            // Route53 is a global namespace → us-east-1 CloudWatch (like CloudFront).
            let cw = self.aws_clients.cloudwatch_us_east_1_client();
            let tx = event_tx.clone();
            tokio::spawn(async move {
                if let Ok(data) = crate::aws::services::route53::fetch_health_check_metrics(
                    cw,
                    id.clone(),
                    time_range,
                )
                .await
                {
                    let _ = tx.send(Event::R53HealthCheckMetricsLoaded { id, data });
                }
            });
        }
    }

    /// Trigger a lazy-load of records for the currently selected zone if not yet loaded.
    pub(crate) fn trigger_r53_records_load(&mut self, event_tx: &mpsc::UnboundedSender<Event>) {
        if let Some(zone) = self.get_selected_resource()
            .and_then(|r| r.as_any().downcast_ref::<crate::aws::services::route53::R53HostedZone>())
        {
            let (zone_id, zone_name) = (zone.id.clone(), zone.name.clone());
            let client = self.aws_clients.route53_client();
            self.trigger_lazy(
                |app| &mut app.lazy.r53_zone_records,
                zone_id.clone(),
                event_tx,
                async move {
                    crate::aws::services::route53::fetch_zone_records(&client, &zone_id, &zone_name)
                        .await
                },
            );
        }
    }

    /// The cross-zone Records sub-tab: fetch every loaded zone's records
    /// (through the same `r53_zone_records` map the zone pane uses, so
    /// neither refetches the other's) and flatten them into the list as
    /// `R53Record` rows. One task walks the zones **sequentially** — Route 53
    /// throttles at 5 requests/s account-wide, and a hundred concurrent
    /// `ListResourceRecordSets` calls would mostly be retries. Two budgets
    /// keep a keystroke from turning into minutes of paging: zones over
    /// `MAX_R53_TAB_ZONE_RECORDS` records (the count is free, it comes with
    /// `ListHostedZones`) and zones past `MAX_R53_TAB_ZONES` per trigger are
    /// skipped and reported in the tab strip; the zone pane still loads any
    /// of them on demand.
    pub(crate) fn trigger_r53_all_records_load(&mut self, event_tx: &mpsc::UnboundedSender<Event>) {
        use crate::aws::services::route53::R53HostedZone;
        let mut todo: Vec<(String, String)> = Vec::new();
        let mut skipped_big = 0usize;
        let mut skipped_budget = 0usize;
        for r in &self.resources {
            let Some(z) = r.as_any().downcast_ref::<R53HostedZone>() else {
                continue;
            };
            if self.lazy.r53_zone_records.contains(&z.id) {
                continue;
            }
            if z.record_count > MAX_R53_TAB_ZONE_RECORDS {
                skipped_big += 1;
                continue;
            }
            if todo.len() >= MAX_R53_TAB_ZONES {
                skipped_budget += 1;
                continue;
            }
            todo.push((z.id.clone(), z.name.clone()));
        }
        self.r53_records_skipped = (skipped_big, skipped_budget);
        if todo.is_empty() {
            return;
        }
        for (id, _) in &todo {
            self.lazy.r53_zone_records.insert_loading(id.clone());
        }
        let epoch = self.lazy.epoch();
        let tx = event_tx.clone();
        let client = self.aws_clients.route53_client();
        tokio::spawn(async move {
            for (zone_id, zone_name) in todo {
                let result =
                    crate::aws::services::route53::fetch_zone_records(&client, &zone_id, &zone_name)
                        .await;
                let key = zone_id;
                let sent = tx.send(Event::Lazy(crate::lazy::LazyApply {
                    epoch,
                    apply: Box::new(move |app| {
                        app.lazy.r53_zone_records.apply(key, result);
                        app.sync_r53_record_rows();
                    }),
                }));
                if sent.is_err() {
                    break;
                }
            }
        });
    }

    /// Records sub-tab entry (`2` / `Tab`): start the cross-zone fetch and
    /// flatten whatever is already loaded.
    fn enter_r53_records_tab(&mut self, event_tx: &mpsc::UnboundedSender<Event>) {
        self.trigger_r53_all_records_load(event_tx);
        self.sync_r53_record_rows();
    }

    /// Selected hosted zone's query-log destination `(group, region)`, once
    /// its Info bundle has loaded. `None` while unloaded or when query
    /// logging is off — `t`'s error message tells the two apart.
    fn r53_zone_query_log(&self) -> Option<(String, String)> {
        let zone = self
            .get_selected_resource()?
            .as_any()
            .downcast_ref::<crate::aws::services::route53::R53HostedZone>()?;
        match self.lazy.r53_zone_detail.get(&zone.id) {
            Some(crate::lazy::Lazy::Loaded(d)) => d.query_log_group.clone(),
            _ => None,
        }
    }

