    fn selected_r53_record(&self) -> Option<&crate::aws::services::route53::R53Record> {
        self.get_selected_resource()
            .and_then(|r| r.as_any().downcast_ref::<crate::aws::services::route53::R53Record>())
    }

    /// Mirror every loaded zone's records into `self.resources` as
    /// `R53Record` rows (idempotent — keyed by zone id, so a zone already
    /// flattened is skipped). Runs on Records-tab entry, after each zone's
    /// fetch lands, and after a list reload/watch swap (which rebuilds the
    /// list from zones + health checks alone). Re-stamps the cache so `@all`
    /// and the `U` lens see the records too — only when no list load is
    /// streaming, since the full-load handler stamps its own.
    pub(crate) fn sync_r53_record_rows(&mut self) {
        use crate::aws::services::route53::R53Record;
        if self.current_service != Some(ServiceType::Route53) || self.all_search_mode {
            return;
        }
        let present: std::collections::HashSet<String> = self
            .resources
            .iter()
            .filter_map(|r| r.as_any().downcast_ref::<R53Record>())
            .map(|r| r.zone_id.clone())
            .collect();
        let mut added: Vec<Box<dyn Resource>> = Vec::new();
        for (zone_id, state) in self.lazy.r53_zone_records.iter() {
            if present.contains(zone_id) {
                continue;
            }
            if let crate::lazy::Lazy::Loaded(records) = state {
                added.extend(
                    records
                        .iter()
                        .map(|r| Box::new(r.clone()) as Box<dyn Resource>),
                );
            }
        }
        if added.is_empty() {
            return;
        }
        self.resources.extend(added);
        if !self.loading && self.watch_staging.is_none() {
            self.cache
                .insert(ServiceType::Route53, self.current_region, None, self.resources.clone());
        }
        self.update_search();
    }

    /// Lazy-load a hosted zone's VPC associations + pending authorizations +
    /// tags on first view of the Sharing or Tags section, keyed by zone id.
    pub(crate) fn trigger_r53_zone_detail_load(&mut self, event_tx: &mpsc::UnboundedSender<Event>) {
        use crate::aws::services::route53::R53ZoneDetailSection::*;
        if !matches!(
            crate::aws::services::route53::R53ZoneDetailSection::from_index(self.detail_section_idx),
            Sharing | Info | Tags
        ) {
            return;
        }
        if let Some(zone) = self.get_selected_resource()
            .and_then(|r| r.as_any().downcast_ref::<crate::aws::services::route53::R53HostedZone>())
        {
            let (zone_id, private_zone) = (zone.id.clone(), zone.private_zone);
            let client = self.aws_clients.route53_client();
            self.trigger_lazy(
                |app| &mut app.lazy.r53_zone_detail,
                zone_id.clone(),
                event_tx,
                async move {
                    crate::aws::services::route53::fetch_zone_detail(
                        client, zone_id, private_zone,
                    )
                    .await
                    .map(Box::new)
                    .map_err(|e| format!("Zone detail unavailable: {}", e))
                },
            );
        }
    }

