    pub(crate) fn trigger_code_pipeline_details_load(&mut self, event_tx: &mpsc::UnboundedSender<Event>) {
        if let Some(name) = self.selected_code_pipeline_name() {
            let client = self.aws_clients.codepipeline_client();
            // Neither ListPipelines nor GetPipeline returns an ARN, so the tag
            // lookup needs one built here (the Athena workgroup pattern). No
            // account id yet ⇒ empty, and the fetch skips tags.
            let arn = match &self.account_id {
                Some(account) => format!(
                    "arn:aws:codepipeline:{}:{}:{}",
                    self.current_region.as_str(),
                    account,
                    name
                ),
                None => String::new(),
            };
            self.trigger_lazy(
                |app| &mut app.lazy.code_pipeline_details,
                name.clone(),
                event_tx,
                async move {
                    crate::aws::services::code::fetch_pipeline_details(client, name, arn)
                        .await
                        .map_err(|e| e.to_string())
                },
            );
        }
    }

