    pub(crate) fn trigger_cc_pr_diff_load(&mut self, event_tx: &mpsc::UnboundedSender<Event>) {
        let info = self.selected_cc_pr().map(|p| {
            (
                p.pr_id.clone(),
                p.repo.clone(),
                // Merge base → source tip = "what this PR would add". An
                // empty merge base (rare, e.g. unrelated histories) falls
                // back to the destination commit.
                if p.merge_base.is_empty() {
                    p.dest_commit.clone()
                } else {
                    p.merge_base.clone()
                },
                p.source_commit.clone(),
            )
        });
        if let Some((pr_id, repo, before, after)) = info {
            if repo.is_empty() || before.is_empty() || after.is_empty() {
                return;
            }
            let client = self.aws_clients.codecommit_client();
            self.trigger_lazy(
                |app| &mut app.lazy.cc_pr_diff,
                pr_id.clone(),
                event_tx,
                async move {
                    crate::aws::services::code::fetch_pr_diff(client, repo, before, after).await
                },
            );
        }
    }

    /// `e` on a PR's Changes section: build the full unified patch (blob
    /// fetches + local diff) and open it in `$EDITOR`. Returns `false` when
    /// not on a loaded Changes section, so the `e` chain falls through.
    fn trigger_cc_pr_patch_open(&mut self, event_tx: &mpsc::UnboundedSender<Event>) -> bool {
        if self.selected_cc_pr().is_none()
            || crate::aws::services::code::CcPrDetailSection::from_index(self.detail_section_idx)
                != crate::aws::services::code::CcPrDetailSection::Changes
        {
            return false;
        }
        let Some(pr_id) = self.selected_cc_pr().map(|p| p.pr_id.clone()) else {
            return false;
        };
        let diff = match self.lazy.cc_pr_diff.get(&pr_id) {
            Some(crate::lazy::Lazy::Loaded(d)) => d.clone(),
            _ => return false,
        };
        let client = self.aws_clients.codecommit_client();
        let tx = event_tx.clone();
        self.success_message = Some("Building patch…".to_string());
        tokio::spawn(async move {
            let content = crate::aws::services::code::fetch_pr_patch(client, diff).await;
            let _ = tx.send(crate::event::Event::CcPrPatchLoaded { content });
        });
        true
    }

    /// `Enter` on a `#<id>` row in the repo pane's Pull Requests section
    /// jumps to that PR row on the Pull Requests sub-tab.
    pub(crate) fn cc_repo_pr_row_jump_target(&self, key: &str, value: &str) -> Option<JumpTarget> {
        let repo = self.selected_cc_repo()?;
        if crate::aws::services::code::CodeCommitRepoDetailSection::from_index(
            self.detail_section_idx,
        ) != crate::aws::services::code::CodeCommitRepoDetailSection::PullRequests
        {
            return None;
        }
        let _ = (repo, value);
        let id = key.trim_start().strip_prefix('#')?;
        if id.is_empty() || !id.chars().all(|c| c.is_ascii_digit()) {
            return None;
        }
        Some(JumpTarget {
            service: ServiceType::Code,
            view: JumpView::Code(CodeView::PullRequests),
            id: id.to_string(),
        })
    }

    /// `Enter` on a branch row in the Branches section re-keys the Commits
    /// walk to that branch and switches to the Commits section. Returns
    /// `false` when the selection/section/row isn't a branch row, so the
    /// Enter chain falls through to the resource jump.
    fn try_cc_branch_commits(&mut self, event_tx: &mpsc::UnboundedSender<Event>) -> bool {
        let Some(repo_name) = self.selected_cc_repo().map(|r| r.name.clone()) else {
            return false;
        };
        if crate::aws::services::code::CodeCommitRepoDetailSection::from_index(self.detail_section_idx)
            != crate::aws::services::code::CodeCommitRepoDetailSection::Branches
        {
            return false;
        }
        let rows = self.get_detail_lines_filtered();
        let Some((key, value)) = self.details_selected_index.and_then(|i| rows.get(i).cloned())
        else {
            return false;
        };
        // Branch rows are `("  {name}", "{tip info}")`; skip headers, blanks
        // and `· ` annotation rows.
        let name = key.trim_start();
        if !key.starts_with("  ") || name.is_empty() || name.starts_with('·') || value.is_empty() {
            return false;
        }
        self.cc_commits_branch = Some((repo_name, name.to_string()));
        self.set_detail_section(
            crate::aws::services::code::CodeCommitRepoDetailSection::Commits as usize,
            event_tx,
        );
        true
    }

