    /// Fetch the buildspec file from the source repo for a project whose
    /// buildspec is a file path (not inline). CodeCommit sources are pulled via
    /// `GetFile`; a `CODEPIPELINE` source is resolved through the pipeline (its
    /// Source stage holds the real repo); other sources (GitHub/S3/…) are
    /// marked unsupported.
    pub(crate) fn trigger_code_build_buildspec_load(&mut self, event_tx: &mpsc::UnboundedSender<Event>) {
        use crate::aws::services::code::CodeBuildProject;
        let target = self.get_selected_resource().and_then(|r| {
            r.as_any().downcast_ref::<CodeBuildProject>().map(|p| {
                (
                    p.name.clone(),
                    p.buildspec.clone(),
                    p.buildspec_is_inline(),
                    p.source_type.clone(),
                    p.source_location.clone(),
                    p.source_version.clone(),
                )
            })
        });
        let Some((name, buildspec, inline, source_type, source_location, source_version)) = target
        else {
            return;
        };
        // Inline buildspecs need no fetch — they're already in hand.
        if inline || self.lazy.code_build_buildspecs.contains(&name) {
            return;
        }

        // CODEPIPELINE source: the buildspec lives in the pipeline's source
        // artifact, not on the project. Resolve via the pipeline definitions.
        if source_type == "CODEPIPELINE" {
            let cp = self.aws_clients.codepipeline_client();
            let cc = self.aws_clients.codecommit_client();
            self.trigger_lazy(
                |app| &mut app.lazy.code_build_buildspecs,
                name.clone(),
                event_tx,
                async move {
                    crate::aws::services::code::fetch_codebuild_buildspec_via_pipeline(
                        cp, cc, name, buildspec,
                    )
                    .await
                },
            );
            return;
        }

        if source_type != "CODECOMMIT" {
            let note = if source_location.is_empty() {
                format!("Buildspec lives in the {} source", source_type)
            } else {
                format!("Buildspec lives in {} ({})", source_type, source_location)
            };
            self.lazy.code_build_buildspecs.apply(
                name,
                Ok(crate::aws::services::code::BuildspecResult::Unsupported(note)),
            );
            return;
        }

        let Some(repo) =
            crate::aws::services::code::codecommit_repo_from_location(&source_location)
        else {
            self.lazy
                .code_build_buildspecs
                .apply(name, Err("Could not resolve the CodeCommit repo".to_string()));
            return;
        };

        let client = self.aws_clients.codecommit_client();
        let commit = (!source_version.is_empty()).then_some(source_version);
        self.trigger_lazy(
            |app| &mut app.lazy.code_build_buildspecs,
            name,
            event_tx,
            async move {
                crate::aws::services::code::fetch_codebuild_buildspec(
                    client, repo, buildspec, commit,
                )
                .await
            },
        );
    }

    /// The build under the detail cursor in the Builds section, if any — so `t`
    /// can tail that specific build's logs (console-style) rather than the latest.
    fn selected_code_build_build(&self) -> Option<crate::aws::services::code::CodeBuildBuild> {
        if crate::aws::services::code::CodeBuildDetailSection::from_index(self.detail_section_idx) != CodeBuildDetailSection::Builds {
            return None;
        }
        let name = self
            .get_selected_resource()?
            .as_any()
            .downcast_ref::<crate::aws::services::code::CodeBuildProject>()?
            .name
            .clone();
        let state = self.lazy.code_build_builds.get(&name)?;
        let crate::lazy::Lazy::Loaded(builds) = state else {
            return None;
        };
        if builds.is_empty() {
            return None;
        }
        let (_lines, starts) =
            crate::ui::widgets::details_pane::code_build_builds_lines_indexed(Some(state));
        let sel = self.details_selected_index.unwrap_or(0);
        let mut idx = 0;
        for (i, &start) in starts.iter().enumerate() {
            if start <= sel {
                idx = i;
            } else {
                break;
            }
        }
        builds.get(idx).cloned()
    }

    /// The pipeline-run action whose logs `t` should tail: the one under the
    /// cursor on the Actions section, else the first action of the run that
    /// emitted a log stream at all (so `t` works from Overview too).
    fn selected_code_action_execution(
        &self,
    ) -> Option<crate::aws::services::code::PipelineActionExecution> {
        let exec = self.selected_code_pipeline_execution()?;
        let state = self.lazy.code_action_executions.get(&exec.execution_id)?;
        let crate::lazy::Lazy::Loaded(actions) = state else {
            return None;
        };
        let with_logs = || actions.iter().find(|a| !a.log_stream_arn.is_empty()).cloned();
        if crate::aws::services::code::CodeExecDetailSection::from_index(self.detail_section_idx)
            != crate::aws::services::code::CodeExecDetailSection::Actions
        {
            return with_logs();
        }
        let (_lines, starts) =
            crate::ui::widgets::details_pane::code_exec_actions_lines_indexed(Some(state));
        let sel = self.details_selected_index.unwrap_or(0);
        let mut idx = None;
        for (i, &start) in starts.iter().enumerate() {
            if start <= sel {
                idx = Some(i);
            } else {
                break;
            }
        }
        // The cursor's action only helps if it actually logged something;
        // otherwise fall back rather than erroring on a Source action.
        match idx.and_then(|i| actions.get(i)) {
            Some(a) if !a.log_stream_arn.is_empty() => Some(a.clone()),
            _ => with_logs(),
        }
    }

    /// Resolve the access-log CloudWatch group for `t` on a REST/HTTP API. Prefers
    /// the access-log row under the cursor (so you can tail a specific stage),
    /// else the first stage that has access logging configured. Returns
    /// `(log_group_name, title)`.
    fn selected_api_stage_log(&self) -> Option<(String, String)> {
        use crate::aws::services::api_gateway::{
            ApiStage, HttpApi, RestApi};

        // Strip `arn:…:log-group:NAME[:*]` → NAME.
        fn group_from_arn(arn: &str) -> Option<String> {
            let idx = arn.find(":log-group:")?;
            let rest = &arn[idx + ":log-group:".len()..];
            Some(rest.strip_suffix(":*").unwrap_or(rest).to_string())
        }

        let resource = self.get_selected_resource()?;
        let (stages, api_name): (&[ApiStage], String) = if let Some(api) =
            resource.as_any().downcast_ref::<RestApi>()
        {
            match self.lazy.rest_api_details.get(&api.id) {
                Some(crate::lazy::Lazy::Loaded(d)) => (&d.stages, api.name().to_string()),
                _ => return None}
        } else if let Some(api) = resource.as_any().downcast_ref::<HttpApi>() {
            match self.lazy.http_api_details.get(&api.id) {
                Some(crate::lazy::Lazy::Loaded(d)) => (&d.stages, api.name().to_string()),
                _ => return None}
        } else {
            return None;
        };

        // 1. The access-log row under the cursor (value is the logs ARN).
        if let Some(idx) = self.details_selected_index {
            if let Some((_, value)) = self.get_detail_lines_filtered().get(idx) {
                if value.contains(":log-group:") {
                    if let Some(group) = group_from_arn(value) {
                        // Find the owning stage for a nicer title.
                        let stage = stages
                            .iter()
                            .find(|s| s.access_log_destination == *value)
                            .map(|s| s.name.clone())
                            .unwrap_or_default();
                        let title = if stage.is_empty() {
                            format!("{} access logs", api_name)
                        } else {
                            format!("{} [{}] access logs", api_name, stage)
                        };
                        return Some((group, title));
                    }
                }
            }
        }

        // 2. First stage with access logging.
        let stage = stages
            .iter()
            .find(|s| !s.access_log_destination.is_empty())?;
        let group = group_from_arn(&stage.access_log_destination)?;
        Some((group, format!("{} [{}] access logs", api_name, stage.name)))
    }

