    /// `ListTagsForResource` on the selected workgroup — needs a full ARN, built
    /// from the account id + current region (the SDK returns no ARN).
    pub(crate) fn trigger_athena_workgroup_tags_load(&mut self, event_tx: &mpsc::UnboundedSender<Event>) {
        let Some(name) = self.get_selected_resource().and_then(|r| {
            r.as_any()
                .downcast_ref::<crate::aws::services::athena::AthenaWorkgroup>()
                .map(|w| w.name.clone())
        }) else {
            return;
        };
        if self.lazy.athena_workgroup_tags.contains(&name) {
            return;
        }
        let Some(account) = self.account_id.clone() else {
            // Without the account id we can't build the ARN — show "no tags".
            self.lazy.athena_workgroup_tags.apply(name, Ok(Vec::new()));
            return;
        };
        let arn = format!(
            "arn:aws:athena:{}:{}:workgroup/{}",
            self.current_region.as_str(),
            account,
            name
        );
        let client = self.aws_clients.athena_client();
        self.trigger_lazy(
            |app| &mut app.lazy.athena_workgroup_tags,
            name,
            event_tx,
            async move {
                crate::aws::services::athena::fetch_athena_workgroup_tags(client, arn)
                    .await
                    .map_err(|e| format!("Tags unavailable: {}", e))
            },
        );
    }

