    /// Lazy-load the selected compliance row's non-compliant resources from
    /// the Config aggregator, keyed by the row's `rule|account|region` key.
    pub(crate) fn trigger_tower_compliance_resources_load(
        &mut self,
        event_tx: &mpsc::UnboundedSender<Event>,
    ) {
        use crate::aws::services::controltower::CtCompliance;
        let target = self.get_selected_resource().and_then(|r| {
            r.as_any().downcast_ref::<CtCompliance>().map(|c| {
                (
                    c.key.clone(),
                    c.aggregator.clone(),
                    c.rule_name.clone(),
                    c.account_id.clone(),
                    c.region.clone(),
                    c.source_account.clone(),
                )
            })
        });
        if let Some((key, aggregator, rule, account, region, source_account)) = target {
            let local_client = self.aws_clients.awsconfig_client();
            // Rows read from the audit account have to be drilled there too —
            // the aggregator doesn't exist in the account being browsed.
            let sdk_config = self.aws_clients.sdk_config().clone();
            let role = self
                .controltower_audit
                .as_ref()
                .map(|(_, role)| role.clone())
                .unwrap_or_else(|| self.org_access_role.clone());
            self.trigger_lazy(
                |app| &mut app.lazy.tower_compliance_resources,
                key,
                event_tx,
                async move {
                    let client = match source_account {
                        Some(id) => aws_sdk_config::Client::new(
                            &crate::aws::client::AwsClients::assume_config_for_account(
                                &sdk_config,
                                &id,
                                &role,
                            )
                            .await,
                        ),
                        None => local_client,
                    };
                    crate::aws::services::controltower::fetch_compliance_resources(
                        client, aggregator, rule, account, region,
                    )
                    .await
                    .map_err(|e| format!("Resources unavailable: {}", e))
                },
            );
        }
    }

