    /// The (map key, ARN, flavor) for an `m`-able AgentCore resource. The ARN
    /// is what the CloudWatch SEARCH matches on; the key is the resource id so
    /// the map lines up with `get_selected_resource().id()` in the renderer.
    fn selected_agentcore_metric_target(
        &self,
    ) -> Option<(
        String,
        String,
        crate::aws::services::agentcore::AgentCoreMetricsFlavor,
    )> {
        use crate::aws::services::agentcore::{
            AgentCoreBrowser, AgentCoreCodeInterpreter, AgentCoreGateway, AgentCoreMemory,
            AgentCoreMetricsFlavor as F, AgentCoreRuntime,
        };
        let r = self.get_selected_resource()?;
        let a = r.as_any();
        if let Some(rt) = a.downcast_ref::<AgentCoreRuntime>() {
            return Some((rt.runtime_id.clone(), rt.arn.clone(), F::Runtime));
        }
        if let Some(m) = a.downcast_ref::<AgentCoreMemory>() {
            return Some((m.memory_id.clone(), m.arn.clone(), F::Memory));
        }
        if let Some(b) = a.downcast_ref::<AgentCoreBrowser>() {
            return Some((b.browser_id.clone(), b.arn.clone(), F::Browser));
        }
        if let Some(c) = a.downcast_ref::<AgentCoreCodeInterpreter>() {
            return Some((
                c.interpreter_id.clone(),
                c.arn.clone(),
                F::CodeInterpreter,
            ));
        }
        if let Some(g) = a.downcast_ref::<AgentCoreGateway>() {
            // `ListGateways` has no ARN and the metric SEARCH matches on one.
            // Prefer the real ARN off the lazy `GetGateway` bundle; fall back
            // to building it from account + region + id so `m` works straight
            // from the list too (the CodePipeline synthesis pattern). Without
            // an account id there is nothing to build from, and the pane just
            // has nothing to query until the bundle lands.
            if let Some(crate::lazy::Lazy::Loaded(d)) =
                self.lazy.agentcore_gateway_detail.get(&g.gateway_id)
            {
                if !d.arn.is_empty() {
                    return Some((g.gateway_id.clone(), d.arn.clone(), F::Gateway));
                }
            }
            if let Some(account) = &self.account_id {
                return Some((
                    g.gateway_id.clone(),
                    format!(
                        "arn:aws:bedrock-agentcore:{}:{}:gateway/{}",
                        self.current_region.as_str(),
                        account,
                        g.gateway_id
                    ),
                    F::Gateway,
                ));
            }
        }
        None
    }

    fn trigger_agentcore_metrics_load(&mut self, event_tx: &mpsc::UnboundedSender<Event>) {
        if let Some((key, arn, flavor)) = self.selected_agentcore_metric_target() {
            let time_range = self.agentcore_metrics_time_range;
            self.agentcore_metrics.insert(
                key.clone(),
                crate::aws::services::agentcore::AgentCoreMetricsState::Loading,
            );
            let cw = self.aws_clients.cloudwatch_client();
            let tx = event_tx.clone();
            tokio::spawn(async move {
                if let Ok(data) = crate::aws::services::agentcore::fetch_agentcore_metrics(
                    cw, arn, flavor, time_range,
                )
                .await
                {
                    let _ = tx.send(crate::event::Event::AgentCoreMetricsLoaded {
                        key,
                        data: Box::new(data),
                    });
                }
            });
        }
    }

