    /// Spawn a lazy-section fetch (idempotent — a key already present in the
    /// target map is a no-op). The result comes back through the single
    /// `Event::Lazy` apply-closure, stamped with the store's current epoch so
    /// a fetch spawned before an account/region switch is dropped, never
    /// applied (docs/adr/0001-apply-closure-lazy-event.md).
    fn trigger_lazy<T, F>(
        &mut self,
        lens: fn(&mut Self) -> &mut crate::lazy::LazyMap<T>,
        key: String,
        event_tx: &mpsc::UnboundedSender<Event>,
        fut: F,
    ) where
        T: Send + 'static,
        F: std::future::Future<Output = std::result::Result<T, String>> + Send + 'static,
    {
        if lens(self).contains(&key) {
            return;
        }
        lens(self).insert_loading(key.clone());
        let epoch = self.lazy.epoch();
        let tx = event_tx.clone();
        tokio::spawn(async move {
            let result = fut.await;
            let _ = tx.send(Event::Lazy(crate::lazy::LazyApply {
                epoch,
                apply: Box::new(move |app| lens(app).apply(key, result))}));
        });
    }

    /// Like `trigger_lazy`, but skips the contains-guard and does **not**
    /// flip the entry to Loading — the stale value keeps rendering until the
    /// fresh result overwrites it. For polling refreshes of an already-loaded
    /// section (the CFN progress rollup); epoch stamping still applies, so a
    /// poll spawned before a credential/region switch is dropped unapplied.
    fn retrigger_lazy<T, F>(
        &mut self,
        lens: fn(&mut Self) -> &mut crate::lazy::LazyMap<T>,
        key: String,
        event_tx: &mpsc::UnboundedSender<Event>,
        fut: F,
    ) where
        T: Send + 'static,
        F: std::future::Future<Output = std::result::Result<T, String>> + Send + 'static,
    {
        let epoch = self.lazy.epoch();
        let tx = event_tx.clone();
        tokio::spawn(async move {
            let result = fut.await;
            let _ = tx.send(Event::Lazy(crate::lazy::LazyApply {
                epoch,
                apply: Box::new(move |app| lens(app).apply(key, result))}));
        });
    }

