    /// Pivot seed for `f` on a CloudTrail event's detail pane: classify the
    /// row under the cursor into a `LookupEvents` attribute + value so the
    /// filter modal opens pre-filled ("everything this user did", "all calls
    /// to this service", "this resource's history"). `None` → unseeded modal.
    fn ct_pivot_seed(
        &self,
    ) -> Option<(crate::aws::services::cloudtrail::CtLookupAttr, String)> {
        use crate::aws::services::cloudtrail::CtLookupAttr;
        if !self.details_focused || !self.is_selected_cloudtrail_event() {
            return None;
        }
        let idx = self.details_selected_index?;
        let rows = self.get_detail_lines_filtered();
        let (key, value) = rows.get(idx)?;
        let value = value.trim();
        if value.is_empty() {
            return None;
        }
        let attr = match key.trim() {
            "Event Name" => CtLookupAttr::EventName,
            "User" | "User Name" => CtLookupAttr::Username,
            "Event Source" => CtLookupAttr::EventSource,
            "Access Key" | "Access Key ID" => CtLookupAttr::AccessKeyId,
            "Event ID" => CtLookupAttr::EventId,
            // Resources-section rows: key = the resource type, value = ARN or
            // name. CloudTrail records ResourceName as the friendly name, so
            // reduce an ARN to its trailing segment (editable in the modal).
            k if k.starts_with("AWS::") || k == "Resource" => {
                let name = value
                    .rsplit(['/', ':'])
                    .next()
                    .filter(|s| !s.is_empty())
                    .unwrap_or(value);
                return Some((CtLookupAttr::ResourceName, name.to_string()));
            }
            _ => return None};
        Some((attr, value.to_string()))
    }

    /// The selected resource's security-group id, whether it's an EC2
    /// `SecurityGroup` or a VPC `VpcSecurityGroup` (both share the split pane).
    fn selected_security_group_id(&self) -> Option<String> {
        let r = self.get_selected_resource()?;
        if let Some(sg) = r
            .as_any()
            .downcast_ref::<crate::aws::services::ec2::SecurityGroup>()
        {
            return Some(sg.group_id.clone());
        }
        if let Some(sg) = r
            .as_any()
            .downcast_ref::<crate::aws::services::vpc::VpcSecurityGroup>()
        {
            return Some(sg.group_id.clone());
        }
        None
    }

