    /// `e` on a version inside the product Versions section: download that
    /// artifact's template body from its presigned URL and open it in
    /// `$EDITOR` (via `Event::ScTemplateLoaded`). The cursor may sit anywhere
    /// in the version's row block — the nearest `ID` row above it names the
    /// artifact. Returns false (fall through to the default editor path)
    /// when the cursor isn't inside a version block or the version has no
    /// template URL (enrichment failed / non-template product).
    fn trigger_sc_template_fetch(&mut self, event_tx: &mpsc::UnboundedSender<Event>) -> bool {
        if !self.details_focused {
            return false;
        }
        let Some(product_id) = self
            .get_selected_resource()
            .and_then(|r| {
                r.as_any()
                    .downcast_ref::<crate::aws::services::servicecatalog::ScProduct>()
            })
            .map(|p| p.id.clone())
        else {
            return false;
        };
        use crate::aws::services::servicecatalog::ScProductDetailSection;
        if ScProductDetailSection::from_index(self.detail_section_idx)
            != ScProductDetailSection::Versions
        {
            return false;
        }
        let Some(idx) = self.details_selected_index else {
            return false;
        };
        let rows = self.get_detail_lines_filtered();
        if idx >= rows.len() {
            return false;
        }
        let id_row = |(key, value): &(String, String)| -> Option<String> {
            (key.trim_start() == "ID" && value.starts_with("pa-")).then(|| value.clone())
        };
        // The version under the cursor — or, when the cursor sits above the
        // first version (the section header), the next one below, so `e` at
        // the top of the section opens the first version's template instead
        // of confusingly falling through to the snapshot editor.
        let Some(artifact_id) = rows[..=idx]
            .iter()
            .rev()
            .find_map(id_row)
            .or_else(|| rows[idx + 1..].iter().find_map(id_row))
        else {
            return false;
        };
        let Some(crate::lazy::Lazy::Loaded(d)) = self.lazy.sc_product_details.get(&product_id)
        else {
            return false;
        };
        let Some(url) = d
            .artifacts
            .iter()
            .find(|a| a.id == artifact_id)
            .map(|a| a.template_url.clone())
            .filter(|u| !u.is_empty())
        else {
            return false;
        };

        self.success_message = Some(format!("Downloading template for {}…", artifact_id));
        self.success_message_time = Some(Instant::now());
        let tx = event_tx.clone();
        // TemplateUrl is usually the raw (unsigned) S3 object URL — fetch
        // those with the authenticated S3 client, pinned to the URL's region.
        match crate::aws::services::servicecatalog::classify_template_url(&url) {
            crate::aws::services::servicecatalog::ScTemplateSource::S3 { bucket, key, region } => {
                let client = match region.as_deref() {
                    Some(r) => self.aws_clients.s3_client_for_region(r),
                    None => self.aws_clients.s3_client(),
                };
                tokio::spawn(async move {
                    let result = crate::aws::services::servicecatalog::fetch_sc_template_body_s3(
                        client, bucket, key,
                    )
                    .await
                    .map_err(|e| e.to_string());
                    let _ = tx.send(Event::ScTemplateLoaded { result });
                });
            }
            crate::aws::services::servicecatalog::ScTemplateSource::Http(url) => {
                tokio::spawn(async move {
                    let result = crate::aws::services::servicecatalog::fetch_sc_template_body(url)
                        .await
                        .map_err(|e| e.to_string());
                    let _ = tx.send(Event::ScTemplateLoaded { result });
                });
            }
        }
        true
    }

