    /// Resolve the `data_json` for a launch template's default version (used by
    /// `v`/`e`). Returns an `Err(message)` to surface in the status bar when the
    /// versions haven't loaded yet.
    fn launch_template_version_data(
        &self,
        lt_id: &str,
        default_version: i64,
    ) -> std::result::Result<String, String> {
        match self.lazy.lt_versions.get(lt_id) {
            Some(crate::lazy::Lazy::Loaded(versions)) => {
                if let Some(v) = versions
                    .iter()
                    .find(|v| v.is_default || v.version_number == default_version)
                    .or_else(|| versions.first())
                {
                    Ok(v.data_json.clone())
                } else {
                    Err("No versions for this launch template".to_string())
                }
            }
            Some(crate::lazy::Lazy::Loading) | None => Err(
                "Template data not loaded yet — open the Versions section (2), then press e"
                    .to_string(),
            ),
            Some(crate::lazy::Lazy::Error(e)) => Err(e.clone())}
    }

    /// (ARN, kind) when the selected resource is one of the five Compute
    /// Optimizer-covered types. EC2/EBS ARNs are built from region + account
    /// id (`None` until `account_id` resolves — the trigger just no-ops and a
    /// later section visit retries).
    fn selected_optimizer_target(
        &self,
    ) -> Option<(String, crate::aws::services::computeoptimizer::CoTargetKind)> {
        use crate::aws::services::computeoptimizer::{self as co, CoTargetKind};
        let r = self.get_selected_resource()?;
        let any = r.as_any();
        if let Some(i) = any.downcast_ref::<crate::aws::services::ec2::Ec2Instance>() {
            let account = self.account_id.as_deref()?;
            return Some((
                co::ec2_instance_arn(self.current_region.as_str(), account, &i.instance_id),
                CoTargetKind::Ec2Instance,
            ));
        }
        if let Some(v) = any.downcast_ref::<crate::aws::services::ec2::EbsVolume>() {
            let account = self.account_id.as_deref()?;
            return Some((
                co::ebs_volume_arn(self.current_region.as_str(), account, &v.volume_id),
                CoTargetKind::EbsVolume,
            ));
        }
        if let Some(f) = any.downcast_ref::<crate::aws::services::lambda::LambdaFunction>() {
            return Some((f.function_arn.clone(), CoTargetKind::LambdaFunction));
        }
        if let Some(g) = any.downcast_ref::<crate::aws::services::asg::AsgGroup>() {
            if g.arn.is_empty() {
                return None;
            }
            return Some((g.arn.clone(), CoTargetKind::Asg));
        }
        if let Some(s) = any.downcast_ref::<crate::aws::services::ecs::EcsServiceInfo>() {
            return Some((s.service_arn.clone(), CoTargetKind::EcsService));
        }
        None
    }

    /// Lazy-load the Optimizer section: fires the one-shot enrollment check,
    /// then the per-resource recommendation (idempotent once Loading/Loaded).
    pub(crate) fn trigger_optimizer_load(&mut self, event_tx: &mpsc::UnboundedSender<Event>) {
        use crate::aws::services::computeoptimizer::{self as co, CoEnrollment};
        if !self.co_enrollment_requested {
            self.co_enrollment_requested = true;
            let client = self.aws_clients.compute_optimizer_client();
            let tx = event_tx.clone();
            tokio::spawn(async move {
                let enrollment = co::fetch_enrollment(client).await;
                let _ = tx.send(Event::CoEnrollmentLoaded { enrollment });
            });
        }
        // A known-unenrolled account can't return recommendations — skip the
        // per-resource call (the section renders the enrollment hint instead).
        if matches!(self.co_enrollment, Some(CoEnrollment::Inactive(_))) {
            return;
        }
        let Some((arn, kind)) = self.selected_optimizer_target() else {
            return;
        };
        let client = self.aws_clients.compute_optimizer_client();
        self.trigger_lazy(
            |app| &mut app.lazy.optimizer_recs,
            arn.clone(),
            event_tx,
            async move { co::fetch_recommendation(client, kind, arn).await },
        );
    }

    /// The Optimizer-section state for the currently selected resource.
    pub fn selected_optimizer_state(
        &self,
    ) -> Option<&crate::lazy::Lazy<Option<crate::aws::services::computeoptimizer::OptimizerRec>>>
    {
        let (arn, _) = self.selected_optimizer_target()?;
        self.lazy.optimizer_recs.get(&arn)
    }

