    /// Counts of loaded sibling IC resources (permission sets, users, groups,
    /// applications) for the instance pane's Summary section — the zero-fetch
    /// "filter siblings" pattern.
    fn ic_sibling_counts(&self) -> (usize, usize, usize, usize) {
        let mut ps = 0;
        let mut users = 0;
        let mut groups = 0;
        let mut apps = 0;
        for r in &self.resources {
            match r.resource_type() {
                "Permission Set" => ps += 1,
                "IC User" => users += 1,
                "IC Group" => groups += 1,
                "IC Application" => apps += 1,
                _ => {}
            }
        }
        (ps, users, groups, apps)
    }

    /// One-shot best-effort Organizations account-name map so assignment /
    /// access rows read `123456789012 (prod)` instead of a bare id.
    fn trigger_ic_account_names_load(&mut self, event_tx: &mpsc::UnboundedSender<Event>) {
        if self.ic_account_names_requested {
            return;
        }
        self.ic_account_names_requested = true;
        let client = self.aws_clients.organizations_client();
        let tx = event_tx.clone();
        tokio::spawn(async move {
            let names =
                crate::aws::services::identity_center::fetch_ic_account_names(client).await;
            let _ = tx.send(crate::event::Event::IcAccountNamesLoaded { names });
        });
    }

    /// Lazy-load a principal's effective account access on first view of the
    /// Access section (user or group), keyed by principal id. Permission set
    /// names resolve from the already-loaded sibling list.
    pub(crate) fn trigger_ic_principal_access_load(&mut self, event_tx: &mpsc::UnboundedSender<Event>) {
        use crate::aws::services::identity_center::{IcGroup, IcUser};
        let target = self.get_selected_resource().and_then(|r| {
            if let Some(u) = r.as_any().downcast_ref::<IcUser>() {
                if crate::aws::services::identity_center::IcUserDetailSection::from_index(self.detail_section_idx) != IcUserDetailSection::Access {
                    return None;
                }
                Some((
                    u.user_id.clone(),
                    u.instance_arn.clone(),
                    u.identity_store_id.clone(),
                    false,
                ))
            } else if let Some(g) = r.as_any().downcast_ref::<IcGroup>() {
                if crate::aws::services::identity_center::IcGroupDetailSection::from_index(self.detail_section_idx) != IcGroupDetailSection::Access {
                    return None;
                }
                Some((
                    g.group_id.clone(),
                    g.instance_arn.clone(),
                    g.identity_store_id.clone(),
                    true,
                ))
            } else {
                None
            }
        });
        let Some((id, instance_arn, identity_store_id, is_group)) = target else {
            return;
        };
        self.trigger_ic_account_names_load(event_tx);
        // Permission-set ARN → name map from the loaded list (zero extra calls).
        let ps_names: std::collections::HashMap<String, String> = self
            .resources
            .iter()
            .filter_map(|r| {
                r.as_any()
                    .downcast_ref::<crate::aws::services::identity_center::PermissionSet>()
                    .map(|ps| (ps.arn.clone(), ps.name.clone()))
            })
            .collect();
        let ssoadmin = self.aws_clients.ssoadmin_client();
        let identitystore = self.aws_clients.identitystore_client();
        self.trigger_lazy(
            |app| &mut app.lazy.ic_principal_access,
            id.clone(),
            event_tx,
            async move {
                crate::aws::services::identity_center::fetch_principal_access(
                    ssoadmin,
                    identitystore,
                    instance_arn,
                    identity_store_id,
                    id,
                    is_group,
                    ps_names,
                )
                .await
                .map_err(|e| format!("Access unavailable: {}", e))
            },
        );
    }

    /// Lazy-load the instance's ABAC config / trusted token issuers on first
    /// view of the respective section, keyed by instance ARN.
    pub(crate) fn trigger_ic_instance_section_load(&mut self, event_tx: &mpsc::UnboundedSender<Event>) {
        let Some(inst) = self.get_selected_resource().and_then(|r| {
            r.as_any()
                .downcast_ref::<crate::aws::services::identity_center::IcInstance>()
        }) else {
            return;
        };
        let arn = inst.instance_arn.clone();
        match crate::aws::services::identity_center::IcInstanceDetailSection::from_index(self.detail_section_idx) {
            IcInstanceDetailSection::Abac => {
                let client = self.aws_clients.ssoadmin_client();
                self.trigger_lazy(
                    |app| &mut app.lazy.ic_abac,
                    arn.clone(),
                    event_tx,
                    async move {
                        crate::aws::services::identity_center::fetch_instance_abac(client, arn)
                            .await
                            .map_err(|e| format!("ABAC configuration unavailable: {}", e))
                    },
                );
            }
            IcInstanceDetailSection::TrustedIssuers => {
                let client = self.aws_clients.ssoadmin_client();
                self.trigger_lazy(
                    |app| &mut app.lazy.ic_tti,
                    arn.clone(),
                    event_tx,
                    async move {
                        crate::aws::services::identity_center::fetch_trusted_token_issuers(
                            client, arn,
                        )
                        .await
                        .map_err(|e| format!("Trusted token issuers unavailable: {}", e))
                    },
                );
            }
            _ => {}
        }
    }

