    /// Open the memory browser at the Actors level. The strategy pick list
    /// for Records mode comes from the memory's already-loaded lazy detail —
    /// if it hasn't been fetched (the store was never drilled into), Records
    /// simply has nothing to scope by and says so.
    fn open_memory_browser(&mut self, event_tx: &mpsc::UnboundedSender<Event>) {
        let Some(m) = self.get_selected_resource().and_then(|r| {
            r.as_any()
                .downcast_ref::<crate::aws::services::agentcore::AgentCoreMemory>()
        }) else {
            return;
        };
        let memory_id = m.memory_id.clone();
        let strategies = match self.lazy.agentcore_memory_detail.get(&memory_id) {
            Some(crate::lazy::Lazy::Loaded(d)) => d
                .strategies
                .iter()
                .map(|s| (s.strategy_id.clone(), s.name.clone()))
                .collect(),
            _ => Vec::new(),
        };
        self.memory_browser.open(memory_id, strategies);
        self.trigger_memory_browser_load(event_tx, false);
    }

    /// Fetch the current level's listing. `append` pages with `next_token`;
    /// otherwise it's a fresh listing.
    fn trigger_memory_browser_load(
        &mut self,
        event_tx: &mpsc::UnboundedSender<Event>,
        append: bool,
    ) {
        use crate::ui::widgets::memory_browser::MemoryLevel;
        let b = &self.memory_browser;
        let (memory_id, actor, session, level) = (
            b.memory_id.clone(),
            b.actor_id.clone(),
            b.session_id.clone(),
            b.level,
        );
        let strategy = b.current_strategy().map(|(id, _)| id.clone());
        let token = if append { b.next_token.clone() } else { None };

        // Records with no strategy to scope by would be a guaranteed
        // ValidationException — render the empty state instead of calling.
        if level == MemoryLevel::Records && strategy.is_none() {
            self.memory_browser.rows.clear();
            self.memory_browser.next_token = None;
            self.memory_browser.loading = false;
            return;
        }

        self.memory_browser.loading = true;
        self.memory_browser.error = None;
        let dp = self.aws_clients.agentcore_client();
        let tx = event_tx.clone();
        tokio::spawn(async move {
            use crate::aws::services::agentcore as ac;
            let result = match level {
                MemoryLevel::Actors => ac::browse_actors(dp, memory_id, token).await,
                MemoryLevel::Sessions => ac::browse_sessions(dp, memory_id, actor, token).await,
                MemoryLevel::Events => {
                    ac::browse_events(dp, memory_id, actor, session, token).await
                }
                MemoryLevel::Records => {
                    ac::browse_records(dp, memory_id, strategy.unwrap_or_default(), token).await
                }
            };
            let _ = match result {
                Ok(page) => tx.send(crate::event::Event::MemoryBrowserLoaded {
                    rows: page.rows,
                    next_token: page.next_token,
                    append,
                }),
                Err(message) => tx.send(crate::event::Event::MemoryBrowserError { message }),
            };
        });
    }

    /// All key handling for the memory browser overlay.
    fn handle_memory_browser_key(
        &mut self,
        key: crossterm::event::KeyEvent,
        event_tx: &mpsc::UnboundedSender<Event>,
    ) {
        use crate::ui::widgets::memory_browser::MemoryLevel;
        use crossterm::event::KeyCode;

        // A message is a one-shot notice; any keypress clears it.
        self.memory_browser.message = None;

        // `?` toggles help from anywhere; while it's open other keys are
        // swallowed so a stray `j` can't move a listing you can't see.
        if key.code == KeyCode::Char('?') {
            self.memory_browser.show_help = !self.memory_browser.show_help;
            return;
        }
        if self.memory_browser.show_help {
            if matches!(key.code, KeyCode::Esc) {
                self.memory_browser.show_help = false;
            }
            return;
        }

        // Filter editing owns every printable key while active.
        if self.memory_browser.filtering {
            match key.code {
                KeyCode::Esc => {
                    self.memory_browser.filtering = false;
                    self.memory_browser.filter.clear();
                    self.memory_browser.selected = 0;
                }
                KeyCode::Enter => self.memory_browser.filtering = false,
                KeyCode::Backspace => {
                    self.memory_browser.filter.pop();
                    self.memory_browser.selected = 0;
                }
                KeyCode::Char(c) => {
                    self.memory_browser.filter.push(c);
                    self.memory_browser.selected = 0;
                }
                _ => {}
            }
            return;
        }

        let mut reload = false;
        let mut page = false;
        match key.code {
            KeyCode::Esc => self.memory_browser.close(),
            KeyCode::Char('/') => self.memory_browser.filtering = true,
            KeyCode::Char('j') | KeyCode::Down => {
                let n = self.memory_browser.filtered_indices().len();
                if n > 0 && self.memory_browser.selected + 1 < n {
                    self.memory_browser.selected += 1;
                    self.memory_browser.detail_scroll = 0;
                }
            }
            KeyCode::Char('k') | KeyCode::Up => {
                self.memory_browser.selected = self.memory_browser.selected.saturating_sub(1);
                self.memory_browser.detail_scroll = 0;
            }
            KeyCode::Char('g') => self.memory_browser.selected = 0,
            KeyCode::Char('G') => {
                let n = self.memory_browser.filtered_indices().len();
                self.memory_browser.selected = n.saturating_sub(1);
            }
            KeyCode::Char('i') => {
                self.memory_browser.show_detail = !self.memory_browser.show_detail;
                self.memory_browser.detail_scroll = 0;
            }
            // Payload scrolling, so a long turn is readable without $EDITOR.
            KeyCode::Char('J') => self.memory_browser.detail_scroll += 1,
            KeyCode::Char('K') => {
                self.memory_browser.detail_scroll =
                    self.memory_browser.detail_scroll.saturating_sub(1)
            }
            KeyCode::Enter | KeyCode::Char('l') | KeyCode::Right => {
                // Drill: Actors → Sessions → Events. Events and Records are
                // leaves — there open the payload preview instead.
                let Some(row) = self.memory_browser.selected_row().cloned() else {
                    return;
                };
                match self.memory_browser.level {
                    MemoryLevel::Actors => {
                        self.memory_browser.reset_listing();
                        self.memory_browser.actor_id = row.id;
                        self.memory_browser.level = MemoryLevel::Sessions;
                        reload = true;
                    }
                    MemoryLevel::Sessions => {
                        self.memory_browser.reset_listing();
                        self.memory_browser.session_id = row.id;
                        self.memory_browser.level = MemoryLevel::Events;
                        reload = true;
                    }
                    MemoryLevel::Events | MemoryLevel::Records => {
                        self.memory_browser.show_detail = true;
                        self.memory_browser.detail_scroll = 0;
                    }
                }
            }
            KeyCode::Char('h') | KeyCode::Left | KeyCode::Backspace => {
                // Up a level; from Actors (or Records) `h` closes, mirroring
                // the S3 browser's root behaviour.
                match self.memory_browser.level {
                    MemoryLevel::Events => {
                        self.memory_browser.reset_listing();
                        self.memory_browser.session_id.clear();
                        self.memory_browser.level = MemoryLevel::Sessions;
                        reload = true;
                    }
                    MemoryLevel::Sessions => {
                        self.memory_browser.reset_listing();
                        self.memory_browser.actor_id.clear();
                        self.memory_browser.level = MemoryLevel::Actors;
                        reload = true;
                    }
                    MemoryLevel::Actors | MemoryLevel::Records => self.memory_browser.close(),
                }
            }
            KeyCode::Char('t') => {
                // Records ⇄ the event drill path. Returning always lands at
                // Actors: the previous drill position is scoped to an actor
                // and session that Records mode doesn't track.
                self.memory_browser.reset_listing();
                if self.memory_browser.level == MemoryLevel::Records {
                    self.memory_browser.level = MemoryLevel::Actors;
                    self.memory_browser.actor_id.clear();
                    self.memory_browser.session_id.clear();
                } else {
                    self.memory_browser.level = MemoryLevel::Records;
                }
                reload = true;
            }
            KeyCode::Char('[') | KeyCode::Char(']')
                if self.memory_browser.level == MemoryLevel::Records =>
            {
                let n = self.memory_browser.strategies.len();
                if n > 1 {
                    let fwd = key.code == KeyCode::Char(']');
                    self.memory_browser.strategy_idx = if fwd {
                        (self.memory_browser.strategy_idx + 1) % n
                    } else {
                        (self.memory_browser.strategy_idx + n - 1) % n
                    };
                    self.memory_browser.reset_listing();
                    reload = true;
                }
            }
            KeyCode::Char('n') => {
                if self.memory_browser.next_token.is_some() {
                    page = true;
                } else {
                    self.memory_browser.message = Some("No more pages".to_string());
                }
            }
            KeyCode::Char('r') => {
                self.memory_browser.reset_listing();
                reload = true;
            }
            KeyCode::Char('y') => {
                if let Some(row) = self.memory_browser.selected_row() {
                    let text = row.detail.clone();
                    self.copy_to_clipboard(&text, "payload");
                    self.memory_browser.message = Some("Copied payload".to_string());
                }
            }
            KeyCode::Char('e') => {
                // Reuses the stash-then-flag path every async editor open
                // uses; main.rs tears the TUI down on the next loop.
                if let Some(row) = self.memory_browser.selected_row() {
                    self.pending_editor_content = Some((row.detail.clone(), ".txt".to_string()));
                    self.editor_requested = true;
                }
            }
            KeyCode::Char('Z') => {
                self.layout_mode = match self.layout_mode {
                    LayoutMode::DetailsOnly => LayoutMode::Split,
                    _ => LayoutMode::DetailsOnly};
            }
            _ => {}
        }

        if reload || page {
            self.trigger_memory_browser_load(event_tx, page);
        }
    }

    fn open_ddb_browser(&mut self, event_tx: &mpsc::UnboundedSender<Event>) {
        if let Some(t) = self.selected_ddb_table() {
            let table = t.name.clone();
            let indexes = t.queryable_indexes();
            self.ddb_browser.open(table, indexes);
            // Auto-run a first-page Scan so items show immediately.
            self.ddb_browser.focus =
                crate::ui::widgets::ddb_item_browser::BrowserFocus::Results;
            self.trigger_ddb_query(event_tx, false);
        }
    }

    /// Execute the browser's current Scan/Query (or fetch the next page).
    fn trigger_ddb_query(&mut self, event_tx: &mpsc::UnboundedSender<Event>, append: bool) {
        use crate::aws::services::dynamodb::DdbQuerySpec;
        let b = &self.ddb_browser;
        let Some(idx) = b.current_index() else {
            return;
        };
        // A Query needs a partition-key value; fall back to Scan otherwise.
        let query = b.query_mode && !b.pk_value.trim().is_empty();
        let spec = DdbQuerySpec {
            table: b.table.clone(),
            index_name: if idx.name.is_empty() {
                None
            } else {
                Some(idx.name.clone())
            },
            query,
            pk_name: idx.pk_name.clone(),
            pk_type: idx.pk_type.clone(),
            pk_value: b.pk_value.trim().to_string(),
            sk_name: idx.sk_name.clone(),
            sk_type: idx.sk_type.clone(),
            sk_op: b.sk_op,
            sk_value: b.sk_value.clone(),
            filter: b.filter.clone(),
            start_key: if append { b.last_key.clone() } else { None }};
        self.ddb_browser.loading = true;
        self.ddb_browser.error = None;
        let client = self.aws_clients.dynamodb_client();
        let tx = event_tx.clone();
        tokio::spawn(async move {
            match crate::aws::services::dynamodb::run_ddb_read(client, spec).await {
                Ok(page) => {
                    let _ = tx.send(crate::event::Event::DdbItemsLoaded {
                        items: page.items,
                        last_key: page.last_key,
                        scanned: page.scanned,
                        append});
                }
                Err(e) => {
                    let _ = tx.send(crate::event::Event::DdbItemsError {
                        message: e.to_string()});
                }
            }
        });
    }

    /// All key handling for the DynamoDB item browser overlay. Splits between
    /// editing the query bar (Query focus) and navigating results (Results focus).
    fn handle_ddb_browser_key(
        &mut self,
        key: crossterm::event::KeyEvent,
        event_tx: &mpsc::UnboundedSender<Event>,
    ) {
        use crate::ui::widgets::ddb_item_browser::{BrowserFocus, QueryField};
        use crossterm::event::KeyCode;

        // `?` toggles the examples cheat-sheet from anywhere; while it's open,
        // Esc/? dismiss it and other keys pass through underneath.
        if key.code == KeyCode::Char('?') {
            self.ddb_browser.show_help = !self.ddb_browser.show_help;
            return;
        }
        if self.ddb_browser.show_help {
            if matches!(key.code, KeyCode::Esc) {
                self.ddb_browser.show_help = false;
            }
            return;
        }

        let mut run: Option<bool> = None; // Some(append)
        let mut toggle_layout = false;
        {
            let b = &mut self.ddb_browser;
            match b.focus {
                BrowserFocus::Query => match key.code {
                    KeyCode::Esc => b.close(),
                    KeyCode::Enter => {
                        b.focus = BrowserFocus::Results;
                        run = Some(false);
                    }
                    KeyCode::Tab => b.next_field(),
                    KeyCode::Down => b.focus = BrowserFocus::Results,
                    KeyCode::Left | KeyCode::Right => match b.active_field {
                        QueryField::Mode => b.query_mode = !b.query_mode,
                        QueryField::Index => {
                            let n = b.indexes.len();
                            if n > 0 {
                                let fwd = key.code == KeyCode::Right;
                                b.index_sel = if fwd {
                                    (b.index_sel + 1) % n
                                } else {
                                    (b.index_sel + n - 1) % n
                                };
                            }
                        }
                        QueryField::SkOp => b.sk_op = b.sk_op.next(),
                        _ => {}
                    },
                    KeyCode::Backspace => match b.active_field {
                        QueryField::Pk => {
                            b.pk_value.pop();
                        }
                        QueryField::Sk => {
                            b.sk_value.pop();
                        }
                        QueryField::Filter => {
                            b.filter.pop();
                        }
                        _ => {}
                    },
                    KeyCode::Char(c) => match b.active_field {
                        QueryField::Pk => b.pk_value.push(c),
                        QueryField::Sk => b.sk_value.push(c),
                        QueryField::Filter => b.filter.push(c),
                        _ => {}
                    },
                    _ => {}
                },
                BrowserFocus::Results => match key.code {
                    KeyCode::Esc => {
                        if b.show_detail {
                            b.show_detail = false;
                        } else {
                            b.close();
                        }
                    }
                    KeyCode::Char('q') => b.close(),
                    KeyCode::Up | KeyCode::Char('k') => {
                        if b.show_detail {
                            b.detail_scroll = b.detail_scroll.saturating_sub(1);
                        } else if b.selected_row > 0 {
                            b.selected_row -= 1;
                        }
                    }
                    KeyCode::Down | KeyCode::Char('j') => {
                        if b.show_detail {
                            b.detail_scroll += 1;
                        } else if b.selected_row + 1 < b.items.len() {
                            b.selected_row += 1;
                        }
                    }
                    KeyCode::Enter => {
                        b.show_detail = !b.show_detail;
                        b.detail_scroll = 0;
                    }
                    KeyCode::Tab | KeyCode::Char('/') => {
                        b.focus = BrowserFocus::Query;
                        b.show_detail = false;
                    }
                    KeyCode::Char('n') => {
                        if b.last_key.is_some() && !b.loading {
                            run = Some(true);
                        }
                    }
                    KeyCode::Char('Z') => toggle_layout = true,
                    _ => {}
                }}
        }
        if toggle_layout {
            self.layout_mode = match self.layout_mode {
                LayoutMode::DetailsOnly => LayoutMode::Split,
                _ => LayoutMode::DetailsOnly};
        }
        if let Some(append) = run {
            self.trigger_ddb_query(event_tx, append);
        }
    }

    // ── S3 object browser ────────────────────────────────────────────────────

    fn is_selected_s3_bucket(&self) -> bool {
        self.get_selected_resource()
            .and_then(|r| r.as_any().downcast_ref::<crate::aws::services::s3::S3Bucket>())
            .is_some()
    }

    /// `t` — open a live CloudWatch Logs tail for the selected resource (a log
    /// group, or an ECS task's `awslogs` containers). A background loop polls
    /// `filter_log_events` and streams batches in via `LogTailBatch`.
    /// Logs client for the open tail/search pane, honouring the pane's region
    /// override (see `log_tail_region`).
    fn tail_logs_client(&self) -> aws_sdk_cloudwatchlogs::Client {
        match self.log_tail_region.as_deref() {
            Some(r) => self.aws_clients.logs_client_for_region(r),
            None => self.aws_clients.logs_client()}
    }

    fn open_log_tail(&mut self, event_tx: &mpsc::UnboundedSender<Event>) {
        use crate::aws::services::cloudwatch::CwLogGroup;
        use crate::aws::services::ecs::EcsTask;

        // Source carries owned data so it can move into the poll task.
        enum Src {
            Group { group: String, streams: Vec<String> },
            EcsTask {
                task_def: String,
                task_id: String,
                containers: Vec<String>},
            NfwFirewall {
                name: String,
                arn: String},
            WafAcl {
                arn: String},
            CodeBuild {
                project: String},
            // A state machine (or one of its executions) whose log group lives
            // in the DescribeStateMachine logging configuration.
            SfnStateMachine {
                arn: String},
            // A specific build whose log group/stream we already have in hand.
            CodeBuildDirect {
                group: String,
                stream: String,
                start_ms: i64}}

        // On a log group's Streams section, tail just the selected stream.
        let sel_stream = self.selected_log_stream_name();
        // AgentCore runtime log groups are per *endpoint*, so the tail needs
        // an endpoint name up front (the borrow below is exclusive).
        let ac_endpoint = self.agentcore_tail_endpoint();

        // Sources whose log group lives in another region (a multi-region
        // trail's CW Logs group sits in its home region) set this override.
        let mut tail_region_override: Option<String> = None;
        // A hosted zone's query-log group (us-east-1), known once its Info
        // bundle has loaded.
        let r53_query_log = self.r53_zone_query_log();
        let r53_zone_detail_loaded = self.is_selected_r53_zone()
            && self
                .get_selected_resource()
                .and_then(|r| r.as_any().downcast_ref::<crate::aws::services::route53::R53HostedZone>())
                .is_some_and(|z| {
                    matches!(self.lazy.r53_zone_detail.get(&z.id), Some(crate::lazy::Lazy::Loaded(_)))
                });

        let (src, title) = {
            let Some(resource) = self.get_selected_resource() else {
                self.error_message = Some("Nothing to tail".to_string());
                return;
            };
            if let Some(lg) = resource.as_any().downcast_ref::<CwLogGroup>() {
                let (streams, title) = match &sel_stream {
                    Some(s) => (
                        vec![s.clone()],
                        format!("{} [{}]", lg.log_group_name, s.rsplit('/').next().unwrap_or(s)),
                    ),
                    None => (Vec::new(), lg.log_group_name.clone())};
                (
                    Src::Group {
                        group: lg.log_group_name.clone(),
                        streams},
                    title,
                )
            } else if let Some(task) = resource.as_any().downcast_ref::<EcsTask>() {
                let task_id = task.task_arn.rsplit('/').next().unwrap_or("").to_string();
                let containers = task.containers.iter().map(|c| c.name.clone()).collect();
                (
                    Src::EcsTask {
                        task_def: task.task_definition.clone(),
                        task_id,
                        containers},
                    format!("ECS task {}", task.display_name),
                )
            } else if let Some(cluster) = resource
                .as_any()
                .downcast_ref::<crate::aws::services::eks::EksCluster>()
            {
                // Control-plane log group only exists when logging is enabled.
                if cluster.logging_enabled.is_empty() {
                    self.error_message =
                        Some("Enable EKS control-plane logging to tail this cluster".to_string());
                    return;
                }
                (
                    Src::Group {
                        group: format!("/aws/eks/{}/cluster", cluster.name),
                        streams: Vec::new()},
                    format!("EKS {} control plane", cluster.name),
                )
            } else if let Some(rt) = resource
                .as_any()
                .downcast_ref::<crate::aws::services::agentcore::AgentCoreRuntime>()
            {
                // Deterministic group name — no resolve round-trip, like
                // Lambda. Present only once observability is enabled on the
                // runtime; an absent group tails empty.
                (
                    Src::Group {
                        group: rt.log_group_for(&ac_endpoint),
                        streams: Vec::new()},
                    format!("AgentCore {}::{} logs", rt.name(), ac_endpoint),
                )
            } else if let Some(gw) = resource
                .as_any()
                .downcast_ref::<crate::aws::services::agentcore::AgentCoreGateway>()
            {
                (
                    Src::Group {
                        group: gw.log_group(),
                        streams: Vec::new()},
                    format!("AgentCore gateway {} logs", gw.name()),
                )
            } else if let Some(mem) = resource
                .as_any()
                .downcast_ref::<crate::aws::services::agentcore::AgentCoreMemory>()
            {
                (
                    Src::Group {
                        group: mem.log_group(),
                        streams: Vec::new()},
                    format!("AgentCore memory {} logs", mem.memory_id),
                )
            } else if let Some(func) = resource
                .as_any()
                .downcast_ref::<crate::aws::services::lambda::LambdaFunction>()
            {
                // `log_group` honours a LoggingConfig override, else the
                // default `/aws/lambda/<name>` (resolved in from_sdk).
                (
                    Src::Group {
                        group: func.log_group.clone(),
                        streams: Vec::new()},
                    format!("Lambda {} logs", func.function_name),
                )
            } else if let Some(db) = resource
                .as_any()
                .downcast_ref::<crate::aws::services::rds::RdsInstance>()
            {
                match db.preferred_log_group() {
                    Some((group, log_type)) => (
                        Src::Group {
                            group,
                            streams: Vec::new()},
                        format!("RDS {} {} logs", db.db_identifier, log_type),
                    ),
                    None => {
                        self.error_message = Some(
                            "No CloudWatch log exports enabled for this RDS instance".to_string(),
                        );
                        return;
                    }
                }
            } else if let Some(c) = resource
                .as_any()
                .downcast_ref::<crate::aws::services::rds::RdsCluster>()
            {
                match c.preferred_log_group() {
                    Some((group, log_type)) => (
                        Src::Group {
                            group,
                            streams: Vec::new()},
                        format!("RDS {} {} logs", c.cluster_identifier, log_type),
                    ),
                    None => {
                        self.error_message = Some(
                            "No CloudWatch log exports enabled for this RDS cluster".to_string(),
                        );
                        return;
                    }
                }
            } else if let Some(fw) = resource
                .as_any()
                .downcast_ref::<crate::aws::services::network_firewall::NfwFirewall>()
            {
                (
                    Src::NfwFirewall {
                        name: fw.name.clone(),
                        arn: fw.arn.clone()},
                    format!("Firewall {} logs", fw.name),
                )
            } else if let Some(acl) = resource
                .as_any()
                .downcast_ref::<crate::aws::services::waf::WafWebAcl>()
            {
                (
                    Src::WafAcl {
                        arn: acl.arn.clone()},
                    format!("WAF {} logs", acl.name),
                )
            } else if let Some(proj) = resource
                .as_any()
                .downcast_ref::<crate::aws::services::code::CodeBuildProject>()
            {
                // Prefer the build under the cursor (Builds section); the loaded
                // build already carries its log group/stream, so no resolve call.
                if let Some(b) = self.selected_code_build_build() {
                    if b.log_group.is_empty() {
                        self.error_message =
                            Some(format!("Build #{} has no CloudWatch logs", b.build_number));
                        return;
                    }
                    (
                        Src::CodeBuildDirect {
                            group: b.log_group.clone(),
                            stream: b.log_stream.clone(),
                            start_ms: b.start_ms},
                        format!("Build #{} logs", b.build_number),
                    )
                } else {
                    (
                        Src::CodeBuild {
                            project: proj.name.clone()},
                        format!("Build {} — latest logs", proj.name),
                    )
                }
            } else if let Some(exec) = resource
                .as_any()
                .downcast_ref::<crate::aws::services::code::CodePipelineExecution>()
            {
                // An action execution carries a full CloudWatch *stream* ARN,
                // so there's nothing to resolve — split it and tail directly.
                let Some(action) = self.selected_code_action_execution() else {
                    self.error_message = Some(
                        "This run's actions wrote no CloudWatch logs (open the Actions section first)"
                            .to_string(),
                    );
                    return;
                };
                let Some((group, stream)) = action.log_group_and_stream() else {
                    self.error_message = Some(format!(
                        "Action {} wrote no CloudWatch logs",
                        action.action_name
                    ));
                    return;
                };
                let title = format!("{} / {} logs", exec.pipeline_name, action.action_name);
                (
                    Src::CodeBuildDirect {
                        group,
                        stream,
                        start_ms: action.start_ms},
                    title,
                )
            } else if resource
                .as_any()
                .downcast_ref::<crate::aws::services::api_gateway::RestApi>()
                .is_some()
                || resource
                    .as_any()
                    .downcast_ref::<crate::aws::services::api_gateway::HttpApi>()
                    .is_some()
            {
                match self.selected_api_stage_log() {
                    Some((group, title)) => (
                        Src::Group {
                            group,
                            streams: Vec::new()},
                        title,
                    ),
                    None => {
                        self.error_message = Some(
                            "No stage access logging configured (open Stages and select a stage with access logs)"
                                .to_string(),
                        );
                        return;
                    }
                }
            } else if let Some(fh) = resource
                .as_any()
                .downcast_ref::<crate::aws::services::kinesis::FirehoseStream>()
            {
                match fh.error_log_group() {
                    Some(group) => (
                        Src::Group {
                            group: group.to_string(),
                            streams: fh
                                .dest
                                .log_stream
                                .as_ref()
                                .map(|s| vec![s.clone()])
                                .unwrap_or_default()},
                        format!("Firehose {} error logs", fh.name),
                    ),
                    None => {
                        self.error_message = Some(
                            "No CloudWatch error logging enabled for this delivery stream"
                                .to_string(),
                        );
                        return;
                    }
                }
            } else if let Some(run) = resource
                .as_any()
                .downcast_ref::<crate::aws::services::glue::GlueJobRun>()
            {
                // The run's own log group (default `/aws-glue/jobs/output`); the
                // log stream is the run id.
                (
                    Src::Group {
                        group: run.log_group(),
                        streams: vec![run.id.clone()]},
                    format!("Glue job run {} logs", run.id),
                )
            } else if let Some(trail) = resource
                .as_any()
                .downcast_ref::<crate::aws::services::cloudtrail::CloudTrailTrail>()
            {
                // The group's region comes from its ARN (the trail's home
                // region), which may differ from the current region.
                match trail.cw_log_group() {
                    Some((group, region)) => {
                        tail_region_override = Some(region);
                        (
                            Src::Group {
                                group,
                                streams: Vec::new()},
                            format!("Trail {} logs", trail.name),
                        )
                    }
                    None => {
                        self.error_message = Some(
                            "This trail doesn't deliver to CloudWatch Logs (S3 only) — nothing to tail"
                                .to_string(),
                        );
                        return;
                    }
                }
            } else if let Some(zone) = resource
                .as_any()
                .downcast_ref::<crate::aws::services::route53::R53HostedZone>()
            {
                // Query logs always land in us-east-1; the parsed ARN says so.
                match r53_query_log {
                    Some((group, region)) => {
                        tail_region_override = Some(region);
                        (
                            Src::Group {
                                group,
                                streams: Vec::new()},
                            format!("Zone {} query logs", zone.name),
                        )
                    }
                    None => {
                        self.error_message = Some(if r53_zone_detail_loaded {
                            "Query logging isn't enabled for this zone — nothing to tail".to_string()
                        } else {
                            "Open the zone's Info section first (the query-log config loads there)"
                                .to_string()
                        });
                        return;
                    }
                }
            } else if let Some(sm) = resource
                .as_any()
                .downcast_ref::<crate::aws::services::step_functions::SfnStateMachine>()
            {
                // The group is only in the describe response, so resolve it
                // async — unless a Details/Definition visit already cached it.
                match self.lazy.sfn_details.get(&sm.arn) {
                    Some(crate::lazy::Lazy::Loaded(d)) if d.log_group.is_some() => (
                        Src::Group {
                            group: d.log_group.clone().unwrap_or_default(),
                            streams: Vec::new()},
                        format!("State machine {} logs", sm.name),
                    ),
                    _ => (
                        Src::SfnStateMachine {
                            arn: sm.arn.clone()},
                        format!("State machine {} logs", sm.name),
                    ),
                }
            } else if let Some(exec) = resource
                .as_any()
                .downcast_ref::<crate::aws::services::step_functions::SfnExecution>()
            {
                // An execution has no group of its own — it writes into its
                // state machine's. The pane opens on that group; `s` flips to
                // search, where the execution ARN narrows it to this run.
                (
                    Src::SfnStateMachine {
                        arn: exec.state_machine_arn.clone()},
                    format!("{} logs", exec.display_name),
                )
            } else {
                self.error_message = Some(
                    "Live tail is available on log groups, Lambda functions, RDS instances/clusters, ECS tasks, firewalls, WAF web ACLs, CodeBuild projects, API Gateway stages, Firehose streams, Glue job runs, Step Functions state machines/executions, and CloudTrail trails".to_string(),
                );
                return;
            }
        };

        // A CLOUDFRONT-scope web ACL's log group lives in us-east-1 regardless
        // of the current region; a trail's group lives in its home region
        // (tail_region_override). Everything else tails in the current region.
        self.log_tail_region = match &src {
            Src::WafAcl { .. } if self.waf_scope == WafScope::CloudFront => {
                Some("us-east-1".to_string())
            }
            _ => tail_region_override};

        // Stop any prior loop, start a fresh generation.
        self.log_tail_active
            .store(false, std::sync::atomic::Ordering::Relaxed);
        self.log_tail_generation += 1;
        let generation = self.log_tail_generation;
        let active = std::sync::Arc::new(std::sync::atomic::AtomicBool::new(true));
        self.log_tail_active = active.clone();

        self.log_tail = crate::ui::widgets::log_tail::LogTailState::open(title);
        self.log_tail.wrap = self.log_wrap;
        self.details_focused = true;

        // Record the group up-front where we know it synchronously (log groups /
        // EKS control plane) so the tail's `s` can flip to search without a
        // re-resolve. Async-resolved sources (ECS/NFW/CodeBuild) leave it empty.
        if let Src::Group { group, streams } = &src {
            self.log_tail.group = group.clone();
            self.log_tail.streams = streams.clone();
        }

        // Seed from a console-style lookback window (default 15m) so the view
        // shows recent history immediately, then follows. The window is carried
        // on the pane's `range` so `[`/`]` can re-seed and a flip to search
        // inherits it.
        self.log_tail.range = crate::aws::services::cloudwatch::LogSearchRange::M15;
        let now_ms = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .map(|d| d.as_millis() as i64)
            .unwrap_or(0);
        let start_cursor = now_ms - self.log_tail.range.lookback_ms();

        let logs = self.tail_logs_client();
        let ecs = self.aws_clients.ecs_client();
        let nfw = self.aws_clients.network_firewall_client();
        let waf = match self.waf_scope {
            WafScope::CloudFront => self.aws_clients.wafv2_cloudfront_client(),
            WafScope::Regional => self.aws_clients.wafv2_client()};
        let cb = self.aws_clients.codebuild_client();
        let sfn = self.aws_clients.sfn_client();
        let tx = event_tx.clone();
        tokio::spawn(async move {
            use std::sync::atomic::Ordering;
            // Resolve the group + streams (an ECS task needs a task-def lookup).
            // `seed` overrides the start cursor where a source has a meaningful
            // origin (a CodeBuild build seeds from its start so past logs show).
            let (group, streams, seed) = match src {
                Src::Group { group, streams } => (group, streams, start_cursor),
                Src::EcsTask {
                    task_def,
                    task_id,
                    containers} => match crate::aws::services::ecs::resolve_ecs_task_log_streams(
                    ecs, task_def, task_id, containers,
                )
                .await
                {
                    Ok((g, s)) => (g, s, start_cursor),
                    Err(e) => {
                        let _ = tx.send(Event::LogTailError {
                            generation,
                            error: e.to_string()});
                        return;
                    }
                },
                Src::NfwFirewall { name, arn } => {
                    match crate::aws::services::network_firewall::resolve_nfw_log_group(
                        nfw, name, arn,
                    )
                    .await
                    {
                        Ok((g, s)) => (g, s, start_cursor),
                        Err(e) => {
                            let _ = tx.send(Event::LogTailError {
                                generation,
                                error: e.to_string()});
                            return;
                        }
                    }
                }
                Src::WafAcl { arn } => {
                    match crate::aws::services::waf::resolve_waf_log_group(waf, arn).await {
                        Ok((g, s)) => (g, s, start_cursor),
                        Err(e) => {
                            let _ = tx.send(Event::LogTailError {
                                generation,
                                error: e.to_string()});
                            return;
                        }
                    }
                }
                Src::SfnStateMachine { arn } => {
                    match crate::aws::services::step_functions::resolve_sfn_log_group(sfn, arn)
                        .await
                    {
                        Ok((g, s)) => (g, s, start_cursor),
                        Err(e) => {
                            let _ = tx.send(Event::LogTailError {
                                generation,
                                error: e.to_string()});
                            return;
                        }
                    }
                }
                Src::CodeBuild { project } => {
                    match crate::aws::services::code::resolve_codebuild_latest_log(cb, project)
                        .await
                    {
                        // Seed a few seconds before the build started so the
                        // whole log is captured, not just the live tail. Fall
                        // back to the default window if the start time is absent.
                        Ok((g, s, start_ms)) => {
                            let seed = if start_ms > 0 {
                                start_ms - 5_000
                            } else {
                                start_cursor
                            };
                            (g, vec![s], seed)
                        }
                        Err(e) => {
                            let _ = tx.send(Event::LogTailError {
                                generation,
                                error: e.to_string()});
                            return;
                        }
                    }
                }
                Src::CodeBuildDirect {
                    group,
                    stream,
                    start_ms} => {
                    let seed = if start_ms > 0 {
                        start_ms - 5_000
                    } else {
                        start_cursor
                    };
                    let streams = if stream.is_empty() {
                        Vec::new()
                    } else {
                        vec![stream]
                    };
                    (group, streams, seed)
                }
            };

            // Hand the resolved group + streams back to the pane so window
            // re-seed (`[`/`]`) and `s`-to-search work on async-resolved sources.
            let _ = tx.send(Event::LogTailResolved {
                generation,
                group: group.clone(),
                streams: streams.clone()});

            let mut cursor = seed;
            while active.load(Ordering::Relaxed) {
                match crate::aws::services::cloudwatch::poll_log_tail(
                    logs.clone(),
                    group.clone(),
                    streams.clone(),
                    cursor,
                )
                .await
                {
                    Ok((lines, next)) => {
                        cursor = next;
                        if !lines.is_empty() {
                            let _ = tx.send(Event::LogTailBatch { generation, lines });
                        }
                    }
                    Err(e) => {
                        let _ = tx.send(Event::LogTailError {
                            generation,
                            error: e.to_string()});
                    }
                }
                // ~2s poll, but wake every 100ms to close promptly.
                for _ in 0..20 {
                    if !active.load(Ordering::Relaxed) {
                        break;
                    }
                    tokio::time::sleep(std::time::Duration::from_millis(100)).await;
                }
            }
        });
    }

    /// Restart the live tail from a fresh lookback window (`[`/`]` in tail mode).
    /// Only works once the group is known synchronously (log groups + any source
    /// already resolved onto the pane); async-only sources show a hint instead.
    fn reseed_log_tail(&mut self, event_tx: &mpsc::UnboundedSender<Event>) {
        if self.log_tail.group.is_empty() {
            self.log_tail.message =
                Some("window change not available for this source".to_string());
            return;
        }
        // Stop the running loop and claim a new generation.
        self.log_tail_active
            .store(false, std::sync::atomic::Ordering::Relaxed);
        self.log_tail_generation += 1;
        let generation = self.log_tail_generation;
        let active = std::sync::Arc::new(std::sync::atomic::AtomicBool::new(true));
        self.log_tail_active = active.clone();

        // Clear the buffer and re-follow so the reloaded window reads cleanly.
        self.log_tail.lines.clear();
        self.log_tail.scroll = 0;
        self.log_tail.follow = true;

        let now_ms = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .map(|d| d.as_millis() as i64)
            .unwrap_or(0);
        let group = self.log_tail.group.clone();
        let streams = self.log_tail.streams.clone();
        let logs = self.tail_logs_client();
        let tx = event_tx.clone();
        let mut cursor = now_ms - self.log_tail.range.lookback_ms();
        tokio::spawn(async move {
            use std::sync::atomic::Ordering;
            while active.load(Ordering::Relaxed) {
                match crate::aws::services::cloudwatch::poll_log_tail(
                    logs.clone(),
                    group.clone(),
                    streams.clone(),
                    cursor,
                )
                .await
                {
                    Ok((lines, next)) => {
                        cursor = next;
                        if !lines.is_empty() {
                            let _ = tx.send(Event::LogTailBatch { generation, lines });
                        }
                    }
                    Err(e) => {
                        let _ = tx.send(Event::LogTailError {
                            generation,
                            error: e.to_string()});
                    }
                }
                for _ in 0..20 {
                    if !active.load(Ordering::Relaxed) {
                        break;
                    }
                    tokio::time::sleep(std::time::Duration::from_millis(100)).await;
                }
            }
        });
    }

    /// On a log group's Streams section with a stream row selected, the stream
    /// the cursor is on (so `t`/`f` scope to it). `None` otherwise.
    fn selected_log_stream_name(&self) -> Option<String> {
        use crate::aws::services::cloudwatch::CwLogGroup;
        if crate::aws::services::cloudwatch::CwLogGroupDetailSection::from_index(self.detail_section_idx) != CwLogGroupDetailSection::Streams {
            return None;
        }
        let lg = self
            .get_selected_resource()?
            .as_any()
            .downcast_ref::<CwLogGroup>()?;
        let streams = match self.lazy.cw_log_streams.get(&lg.log_group_name)? {
            crate::lazy::Lazy::Loaded(s) => s,
            _ => return None};
        // Map the selected detail row to a stream by its rendered short name
        // (robust against the section's header/hint offsets).
        let idx = self.details_selected_index?;
        let rows = self.get_detail_lines_filtered();
        let (key, _) = rows.get(idx)?;
        let short = key.trim();
        streams
            .iter()
            .find(|s| s.name.rsplit('/').next().unwrap_or(&s.name) == short)
            .map(|s| s.name.clone())
    }

    /// On a log group's Filters section with a metric-filter row (or its pattern
    /// row) under the cursor, that filter's CloudWatch Logs filter pattern — so
    /// `f` can run the metric filter's own pattern against the logs. `None`
    /// otherwise (incl. a match-all filter with an empty pattern).
    fn selected_metric_filter_pattern(&self) -> Option<String> {
        use crate::aws::services::cloudwatch::CwLogGroup;
        if crate::aws::services::cloudwatch::CwLogGroupDetailSection::from_index(self.detail_section_idx) != CwLogGroupDetailSection::Filters {
            return None;
        }
        let lg = self
            .get_selected_resource()?
            .as_any()
            .downcast_ref::<CwLogGroup>()?;
        let crate::lazy::Lazy::Loaded(f) =
            self.lazy.cw_log_group_filters.get(&lg.log_group_name)?
        else {
            return None;
        };
        let idx = self.details_selected_index?;
        let rows = self.get_detail_lines_filtered();
        let (key, val) = rows.get(idx)?;
        let k = key.trim();
        // The "    pattern" row carries the pattern as its value directly.
        if k == "pattern" && !val.is_empty() {
            return Some(val.clone());
        }
        // Otherwise a metric-filter name row → look up its (non-empty) pattern.
        f.metric_filters
            .iter()
            .find(|(name, _)| name == k)
            .map(|(_, pattern)| pattern.clone())
            .filter(|p| !p.is_empty())
    }

    /// Open the quick log-search pane ("Search log group") on the selected log
    /// group. One-shot, server-side `filter_log_events` — no background poll.
    /// On a metric-filter row, pre-seeds the search with that filter's pattern.
    fn open_log_search(&mut self, event_tx: &mpsc::UnboundedSender<Event>) {
        use crate::aws::services::cloudwatch::CwLogGroup;
        let sel_stream = self.selected_log_stream_name();
        let metric_pattern = self.selected_metric_filter_pattern();
        let Some(group) = self
            .get_selected_resource()
            .and_then(|r| r.as_any().downcast_ref::<CwLogGroup>())
            .map(|lg| lg.log_group_name.clone())
        else {
            self.error_message = Some("Log search is available on log groups".to_string());
            return;
        };
        // Log groups are browsed in the current region — clear any override
        // left by a cross-region tail (CLOUDFRONT-scope WAF).
        self.log_tail_region = None;
        // No background loop in search mode; stop any prior tail.
        self.log_tail_active
            .store(false, std::sync::atomic::Ordering::Relaxed);
        let (streams, title) = match &sel_stream {
            Some(s) => (
                vec![s.clone()],
                format!("Search {} [{}]", group, s.rsplit('/').next().unwrap_or(s)),
            ),
            None => (Vec::new(), format!("Search {}", group))};
        self.log_tail =
            crate::ui::widgets::log_tail::LogTailState::open_search(title, group, streams);
        self.log_tail.wrap = self.log_wrap;
        // Seed the metric filter's pattern so it runs against the logs directly.
        if let Some(pattern) = metric_pattern {
            self.log_tail.query = pattern;
        }
        self.details_focused = true;
        self.run_log_search(event_tx);
    }

    /// Fire a one-shot search for the pane's current group/streams/pattern/range.
    fn run_log_search(&mut self, event_tx: &mpsc::UnboundedSender<Event>) {
        if self.log_tail.group.is_empty() {
            return;
        }
        // Bump the generation so a stale search (or prior tail) can't clobber us.
        self.log_tail_generation += 1;
        let generation = self.log_tail_generation;
        self.log_tail.searching = true;
        self.log_tail.error = None;

        let logs = self.tail_logs_client();
        let group = self.log_tail.group.clone();
        let streams = self.log_tail.streams.clone();
        let pattern = self.log_tail.query.clone();
        let range = self.log_tail.range;
        let now_ms = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .map(|d| d.as_millis() as i64)
            .unwrap_or(0);
        let tx = event_tx.clone();
        tokio::spawn(async move {
            match crate::aws::services::cloudwatch::search_log_events(
                logs, group, streams, pattern, range, now_ms,
            )
            .await
            {
                Ok((lines, capped)) => {
                    let _ = tx.send(Event::LogSearchResults {
                        generation,
                        lines,
                        capped});
                }
                Err(e) => {
                    let _ = tx.send(Event::LogTailError {
                        generation,
                        error: e.to_string()});
                }
            }
        });
    }

    /// Stop the live tail and hide the view.
    fn close_log_tail(&mut self) {
        self.log_tail_active
            .store(false, std::sync::atomic::Ordering::Relaxed);
        self.log_tail.visible = false;
        self.layout_mode = LayoutMode::Split;
    }

    /// Open the change timeline (`W`) for the selected resource: CloudTrail
    /// `LookupEvents` plus alarm history / CFN stack events / ECS deployment
    /// rows, merged in the detail pane. Preserves the current range /
    /// read-toggle when re-opened so `[`/`]`/`a` feel sticky across
    /// resources.
    fn open_trail_lens(&mut self, event_tx: &mpsc::UnboundedSender<Event>) {
        let (keys, title) = match self.get_selected_resource() {
            Some(r) => (r.trail_lookup_keys(), r.name().to_string()),
            None => {
                self.error_message = Some("No resource selected".to_string());
                return;
            }
        };
        if keys.iter().all(|k| k.trim().is_empty()) {
            self.error_message =
                Some("No CloudTrail lookup key for this resource".to_string());
            return;
        }

        let (range, include_reads) = self
            .trail_in_pane
            .as_ref()
            .map(|s| (s.range, s.include_reads))
            .unwrap_or_default();

        self.details_focused = true;
        self.trail_in_pane = Some(crate::ui::widgets::trail_lens::TrailLensState::open(
            title,
            range,
            include_reads,
        ));
        self.seed_trail_lens(event_tx);
    }

    /// Gather the timeline's zero-fetch inputs for the selected resource:
    /// ownership (which also names the CFN source's stack), alarms matched
    /// from the warm CloudWatch cache, and ECS deployment/service-event rows
    /// straight off the struct.
    fn timeline_inputs(
        &self,
        range: crate::aws::services::cloudtrail::TrailRange,
    ) -> TimelineInputs {
        use crate::timeline::TimelineRow;
        let mut out = TimelineInputs::default();
        let Some(r) = self.get_selected_resource() else {
            return out;
        };
        let now = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .map(|d| d.as_secs() as i64)
            .unwrap_or(0);
        let cutoff = now - range.lookback_secs();

        // Ownership — same tag resolution as the detail-pane ribbon,
        // including Lambda's lazy-tags fallback.
        let mut tags = r.tags();
        if tags.is_empty() {
            if let Some(f) = r
                .as_any()
                .downcast_ref::<crate::aws::services::lambda::LambdaFunction>()
            {
                if let Some(crate::lazy::Lazy::Loaded(info)) =
                    self.lazy.lambda_code.get(&f.function_arn)
                {
                    tags = &info.tags;
                }
            }
        }
        let own =
            crate::ownership::resource_ownership(tags, &self.owner_tags, &self.managed_by_tags);
        if !own.is_empty() {
            out.ownership_line = Some(own.summary());
        }
        out.stack = own.stack_name;
        out.logical_id = own.logical_id;

        // Alarms watching this resource, from the warm CloudWatch cache —
        // any dimension value matching the id or name (namespaces disagree
        // on which they use). Cold cache ⇒ the seed adds a coverage note.
        if let Some(cached) =
            self.cache
                .get_ref(&ServiceType::CloudWatch, &self.current_region, None)
        {
            out.cw_cache_warm = true;
            for res in cached {
                if let Some(alarm) = res
                    .as_any()
                    .downcast_ref::<crate::aws::services::cloudwatch::CwAlarm>()
                {
                    if alarm
                        .dimensions
                        .iter()
                        .any(|(_, v)| v == r.id() || v == r.name())
                    {
                        out.alarm_names.push(alarm.alarm_name.clone());
                        if out.alarm_names.len() >= MAX_TIMELINE_ALARMS {
                            break;
                        }
                    }
                }
            }
        }

        // ECS deployments + service events: already on the struct.
        if let Some(svc) = r
            .as_any()
            .downcast_ref::<crate::aws::services::ecs::EcsServiceInfo>()
        {
            out.deploy_rows.extend(
                svc.deployments
                    .iter()
                    .map(TimelineRow::from_deploy)
                    .filter(|row| row.ts_secs >= cutoff),
            );
            out.deploy_rows.extend(
                svc.events
                    .iter()
                    .map(TimelineRow::from_ecs_event)
                    .filter(|row| row.ts_secs >= cutoff),
            );
        }
        out
    }

    /// (Re)start every timeline source for the current lens: recompute the
    /// zero-fetch inputs, mark the async sources pending, and fire them.
    /// Used by open, `[`/`]`, `a` and `r` — sources are cheap enough that a
    /// range/read toggle just re-runs the lot.
    fn seed_trail_lens(&mut self, event_tx: &mpsc::UnboundedSender<Event>) {
        use crate::timeline::TimelineSource;
        let (keys, range, include_reads) = match (
            self.get_selected_resource(),
            self.trail_in_pane.as_ref(),
        ) {
            (Some(r), Some(st)) => (r.trail_lookup_keys(), st.range, st.include_reads),
            _ => return};
        let inputs = self.timeline_inputs(range);
        let alarm_names = inputs.alarm_names;
        let stack = inputs.stack;
        let logical_id = inputs.logical_id;
        if let Some(st) = self.trail_in_pane.as_mut() {
            st.ownership = inputs.ownership_line;
            let mut pending = vec![TimelineSource::Trail];
            if !alarm_names.is_empty() {
                pending.push(TimelineSource::Alarm);
            }
            if stack.is_some() {
                pending.push(TimelineSource::Cfn);
            }
            st.begin(pending);
            if !inputs.cw_cache_warm {
                st.aux_notes.push(
                    "@cloudwatch not loaded — alarm history unavailable".to_string(),
                );
            }
            st.set_rows(TimelineSource::Deploy, inputs.deploy_rows);
        }
        self.trigger_trail_lens_load(
            event_tx,
            keys,
            range,
            include_reads,
            alarm_names,
            stack,
            logical_id,
        );
    }

    /// Fire the async timeline fetches, all generation-guarded: the
    /// CloudTrail `LookupEvents` (primary), per-alarm `DescribeAlarmHistory`,
    /// and the owning stack's `DescribeStackEvents`.
    #[allow(clippy::too_many_arguments)]
    fn trigger_trail_lens_load(
        &mut self,
        event_tx: &mpsc::UnboundedSender<Event>,
        keys: Vec<String>,
        range: crate::aws::services::cloudtrail::TrailRange,
        include_reads: bool,
        alarm_names: Vec<String>,
        stack: Option<String>,
        logical_id: Option<String>,
    ) {
        use crate::timeline::{TimelineRow, TimelineSource};
        self.trail_generation += 1;
        let generation = self.trail_generation;
        let cutoff = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .map(|d| d.as_secs() as i64)
            .unwrap_or(0)
            - range.lookback_secs();

        let client = self.aws_clients.cloudtrail_client();
        let tx = event_tx.clone();
        tokio::spawn(async move {
            match crate::aws::services::cloudtrail::fetch_trail_events(
                client,
                keys,
                range,
                include_reads,
            )
            .await
            {
                Ok(events) => {
                    let _ = tx.send(Event::TrailLensLoaded { generation, events });
                }
                Err(e) => {
                    let _ = tx.send(Event::TrailLensError {
                        generation,
                        error: e.to_string()});
                }
            }
        });

        if !alarm_names.is_empty() {
            let cw = self.aws_clients.cloudwatch_client();
            let tx = event_tx.clone();
            tokio::spawn(async move {
                let mut rows = Vec::new();
                let mut last_err: Option<String> = None;
                for name in alarm_names {
                    match crate::aws::services::cloudwatch::fetch_alarm_history(
                        cw.clone(),
                        name.clone(),
                    )
                    .await
                    {
                        Ok(items) => rows.extend(
                            items
                                .iter()
                                .filter(|i| {
                                    i.item_type == "StateUpdate" && i.ts_secs >= cutoff
                                })
                                .map(|i| TimelineRow::from_alarm(&name, i)),
                        ),
                        Err(e) => last_err = Some(e.to_string()),
                    }
                }
                // A partial result beats an error banner; error only when
                // every alarm's history failed to land.
                let result = match last_err {
                    Some(e) if rows.is_empty() => Err(e),
                    _ => Ok(rows),
                };
                let _ = tx.send(Event::TrailLensAux {
                    generation,
                    source: TimelineSource::Alarm,
                    rows: result,
                });
            });
        }

        if let Some(stack) = stack {
            let cfn = self.aws_clients.cloudformation_client();
            let tx = event_tx.clone();
            tokio::spawn(async move {
                let result = match crate::aws::services::cloudformation::fetch_stack_events(
                    cfn,
                    stack.clone(),
                )
                .await
                {
                    // This resource's own events (by logical id) plus
                    // stack-level rows (their logical id IS the stack name).
                    Ok(events) => Ok(events
                        .iter()
                        .filter(|e| {
                            e.logical_id == stack
                                || logical_id.as_deref().is_some_and(|l| e.logical_id == l)
                        })
                        .filter(|e| e.ts_secs.unwrap_or(0) >= cutoff)
                        .map(TimelineRow::from_cfn)
                        .collect()),
                    Err(e) => Err(e),
                };
                let _ = tx.send(Event::TrailLensAux {
                    generation,
                    source: TimelineSource::Cfn,
                    rows: result,
                });
            });
        }
    }

    /// Re-run every timeline source after a range / read-toggle change.
    fn reseed_trail_lens(&mut self, event_tx: &mpsc::UnboundedSender<Event>) {
        self.seed_trail_lens(event_tx);
    }

    fn close_trail_lens(&mut self) {
        self.trail_in_pane = None;
        self.layout_mode = LayoutMode::Split;
    }

    // ── "Referenced by" lens (`U`) ──────────────────────────────────────

    /// Open the reverse-lookup lens for the selected resource: walk every
    /// warm cache (plus the on-screen list when its cache has lapsed) for
    /// resources that mention this one. Zero API — coverage is reported,
    /// never extended by fetching.
    fn open_refs_lens(&mut self) {
        let (title, keys) = match self.get_selected_resource() {
            Some(r) => (
                r.name().to_string(),
                crate::references::lookup_keys(r.as_ref()),
            ),
            None => {
                self.error_message = Some("No resource selected".to_string());
                return;
            }
        };
        if keys.is_empty() {
            self.error_message = Some("No identifier to look up for this resource".to_string());
            return;
        }
        let mut st = crate::ui::widgets::refs_lens::RefsLensState::open(title, keys);
        self.details_focused = true;
        self.scan_refs_lens(&mut st);
        self.refs_in_pane = Some(st);
    }

    /// The cache walk behind the lens (`r` re-runs it after loading more
    /// services). The current service's live list stands in when its cache
    /// entry has expired, so what's on screen is never excluded.
    fn scan_refs_lens(&self, st: &mut crate::ui::widgets::refs_lens::RefsLensState) {
        let self_id = self
            .get_selected_resource()
            .map(|r| r.id().to_string())
            .unwrap_or_default();
        let mut rows = Vec::new();
        let mut searched = 0usize;
        let mut unloaded = 0usize;
        for svc in ServiceType::all() {
            let variant = self.cache_variant(svc);
            if let Some(list) =
                self.cache.get_ref(&svc, &self.current_region, variant.as_deref())
            {
                searched += 1;
                rows.extend(crate::references::find_references(
                    svc, list, &st.keys, &self_id,
                ));
            } else if Some(svc) == self.current_service && !self.all_search_mode {
                searched += 1;
                rows.extend(crate::references::find_references(
                    svc,
                    &self.resources,
                    &st.keys,
                    &self_id,
                ));
            } else {
                unloaded += 1;
            }
        }
        st.set_rows(rows, searched, unloaded);
    }

    fn close_refs_lens(&mut self) {
        self.refs_in_pane = None;
        self.layout_mode = LayoutMode::Split;
    }

    /// Key handling while the "referenced by" lens owns the detail pane.
    fn handle_refs_lens_key(
        &mut self,
        key: crossterm::event::KeyEvent,
        event_tx: &mpsc::UnboundedSender<Event>,
    ) {
        use crossterm::event::{KeyCode, KeyModifiers};

        if let Some(st) = self.refs_in_pane.as_mut() {
            st.message = None;
        }
        let viewport = 20usize;

        match key.code {
            KeyCode::Esc | KeyCode::Char('q') | KeyCode::Char('U') => self.close_refs_lens(),
            KeyCode::Char('j') | KeyCode::Down => {
                if let Some(st) = self.refs_in_pane.as_mut() {
                    st.scroll_down(1);
                }
            }
            KeyCode::Char('k') | KeyCode::Up => {
                if let Some(st) = self.refs_in_pane.as_mut() {
                    st.scroll_up(1);
                }
            }
            KeyCode::Char('d') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                if let Some(st) = self.refs_in_pane.as_mut() {
                    st.scroll_down(viewport / 2);
                }
            }
            KeyCode::Char('u') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                if let Some(st) = self.refs_in_pane.as_mut() {
                    st.scroll_up(viewport / 2);
                }
            }
            KeyCode::PageDown => {
                if let Some(st) = self.refs_in_pane.as_mut() {
                    st.scroll_down(viewport);
                }
            }
            KeyCode::PageUp => {
                if let Some(st) = self.refs_in_pane.as_mut() {
                    st.scroll_up(viewport);
                }
            }
            KeyCode::Char('g') => {
                if let Some(st) = self.refs_in_pane.as_mut() {
                    st.goto_top();
                }
            }
            KeyCode::Char('G') => {
                if let Some(st) = self.refs_in_pane.as_mut() {
                    st.goto_bottom();
                }
            }
            KeyCode::Char('f') => {
                if let Some(st) = self.refs_in_pane.as_mut() {
                    st.cycle_service_filter();
                }
            }
            // Re-walk the caches — after loading another service, say.
            KeyCode::Char('r') => {
                if let Some(mut st) = self.refs_in_pane.take() {
                    self.scan_refs_lens(&mut st);
                    st.message = Some("rescanned".to_string());
                    self.refs_in_pane = Some(st);
                }
            }
            // Go to the referencing resource (closes the lens; Ctrl-O returns).
            KeyCode::Enter | KeyCode::Char('l') | KeyCode::Right => {
                let target = self
                    .refs_in_pane
                    .as_ref()
                    .and_then(|st| st.selected_row())
                    .map(|row| (row.service, row.id.clone(), row.resource_type.clone()));
                if let Some((svc, id, rtype)) = target {
                    self.close_refs_lens();
                    self.record_location();
                    self.jump_to_cached_resource(svc, id, &rtype, false, event_tx);
                }
            }
            KeyCode::Char('y') => {
                if let Some(id) = self
                    .refs_in_pane
                    .as_ref()
                    .and_then(|st| st.selected_row())
                    .map(|row| row.id.clone())
                {
                    self.copy_to_clipboard(&id, "id");
                }
            }
            KeyCode::Char('Z') => {
                self.layout_mode = match self.layout_mode {
                    LayoutMode::DetailsOnly => LayoutMode::Split,
                    _ => LayoutMode::DetailsOnly,
                };
            }
            _ => {}
        }
    }

    // ── Network-access lens (`N`) ───────────────────────────────────────

    /// Open the merged security-group view for the selected resource.
    /// Groups already in the warm EC2 / VPC caches (or on screen) resolve
    /// instantly; the rest come from one `DescribeSecurityGroups`.
    fn open_access_lens(&mut self, event_tx: &mpsc::UnboundedSender<Event>) {
        let (title, ids) = match self.get_selected_resource() {
            Some(r) => {
                let mut ids: Vec<String> = Vec::new();
                for id in r.security_group_ids() {
                    let id = id.trim().to_string();
                    if !id.is_empty() && !ids.contains(&id) {
                        ids.push(id);
                    }
                }
                (r.name().to_string(), ids)
            }
            None => {
                self.error_message = Some("No resource selected".to_string());
                return;
            }
        };
        if ids.is_empty() {
            self.error_message = Some("No security groups on this resource".to_string());
            return;
        }
        // Keep the direction toggle sticky across opens, like the timeline's range.
        let direction = self
            .access_in_pane
            .as_ref()
            .map(|s| s.direction)
            .unwrap_or_default();
        let mut st =
            crate::ui::widgets::access_lens::AccessLensState::open(title, ids, direction);
        st.add_groups(self.cached_security_groups(&st.sg_ids));
        let missing = st.missing();
        self.details_focused = true;
        self.access_in_pane = Some(st);
        if !missing.is_empty() {
            self.trigger_access_lens_fetch(event_tx, missing);
        }
    }

    /// Security groups among `ids` that are already loaded — the EC2 cache
    /// (its Security Groups sub-tab shares the entry), the VPC cache (its
    /// own `VpcSecurityGroup` type, converted), and the on-screen list.
    fn cached_security_groups(
        &self,
        ids: &[String],
    ) -> Vec<crate::aws::services::ec2::SecurityGroup> {
        use crate::aws::services::ec2::SecurityGroup;
        use crate::aws::services::vpc::VpcSecurityGroup;
        let mut found: Vec<SecurityGroup> = Vec::new();
        let mut take = |res: &dyn Resource| {
            if let Some(sg) = res.as_any().downcast_ref::<SecurityGroup>() {
                if ids.contains(&sg.group_id) && !found.iter().any(|f| f.group_id == sg.group_id) {
                    found.push(sg.clone());
                }
            } else if let Some(sg) = res.as_any().downcast_ref::<VpcSecurityGroup>() {
                if ids.contains(&sg.group_id) && !found.iter().any(|f| f.group_id == sg.group_id) {
                    found.push(SecurityGroup {
                        group_id: sg.group_id.clone(),
                        group_name: sg.group_name.clone(),
                        description: sg.description.clone(),
                        vpc_id: sg.vpc_id.clone(),
                        inbound_rules: sg.inbound_rules.clone(),
                        outbound_rules: sg.outbound_rules.clone(),
                        tags: sg.tags.clone(),
                    });
                }
            }
        };
        for svc in [ServiceType::EC2, ServiceType::VPC] {
            if let Some(list) = self.cache.get_ref(&svc, &self.current_region, None) {
                for r in list {
                    take(r.as_ref());
                }
            }
        }
        if !self.all_search_mode
            && matches!(self.current_service, Some(ServiceType::EC2 | ServiceType::VPC))
        {
            for r in &self.resources {
                take(r.as_ref());
            }
        }
        found
    }

    /// One `DescribeSecurityGroups` for the ids no cache had.
    fn trigger_access_lens_fetch(
        &mut self,
        event_tx: &mpsc::UnboundedSender<Event>,
        ids: Vec<String>,
    ) {
        self.access_generation += 1;
        let generation = self.access_generation;
        if let Some(st) = self.access_in_pane.as_mut() {
            st.loading = true;
            st.error = None;
        }
        let client = self.aws_clients.ec2_client();
        let tx = event_tx.clone();
        tokio::spawn(async move {
            let groups = client
                .describe_security_groups()
                .set_group_ids(Some(ids))
                .send()
                .await
                .map(|resp| {
                    resp.security_groups()
                        .iter()
                        .map(crate::aws::services::ec2::SecurityGroup::from_sdk)
                        .collect::<Vec<_>>()
                })
                .map_err(|e| crate::error::sdk_error_message(&e));
            let _ = tx.send(Event::AccessLensLoaded { generation, groups });
        });
    }

    fn close_access_lens(&mut self) {
        self.access_in_pane = None;
        self.layout_mode = LayoutMode::Split;
    }

    /// Key handling while the network-access lens owns the detail pane.
    fn handle_access_lens_key(
        &mut self,
        key: crossterm::event::KeyEvent,
        event_tx: &mpsc::UnboundedSender<Event>,
    ) {
        use crossterm::event::{KeyCode, KeyModifiers};

        if let Some(st) = self.access_in_pane.as_mut() {
            st.message = None;
        }
        let viewport = 20usize;

        match key.code {
            KeyCode::Esc | KeyCode::Char('q') | KeyCode::Char('N') => self.close_access_lens(),
            KeyCode::Char('j') | KeyCode::Down => {
                if let Some(st) = self.access_in_pane.as_mut() {
                    st.scroll_down(1);
                }
            }
            KeyCode::Char('k') | KeyCode::Up => {
                if let Some(st) = self.access_in_pane.as_mut() {
                    st.scroll_up(1);
                }
            }
            KeyCode::Char('d') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                if let Some(st) = self.access_in_pane.as_mut() {
                    st.scroll_down(viewport / 2);
                }
            }
            KeyCode::Char('u') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                if let Some(st) = self.access_in_pane.as_mut() {
                    st.scroll_up(viewport / 2);
                }
            }
            KeyCode::PageDown => {
                if let Some(st) = self.access_in_pane.as_mut() {
                    st.scroll_down(viewport);
                }
            }
            KeyCode::PageUp => {
                if let Some(st) = self.access_in_pane.as_mut() {
                    st.scroll_up(viewport);
                }
            }
            KeyCode::Char('g') => {
                if let Some(st) = self.access_in_pane.as_mut() {
                    st.goto_top();
                }
            }
            KeyCode::Char('G') => {
                if let Some(st) = self.access_in_pane.as_mut() {
                    st.goto_bottom();
                }
            }
            // inbound → outbound → both
            KeyCode::Char('t') => {
                if let Some(st) = self.access_in_pane.as_mut() {
                    st.cycle_direction();
                }
            }
            // Refetch every group (rules may have changed since the cache).
            KeyCode::Char('r') => {
                let ids = self.access_in_pane.as_mut().map(|st| {
                    st.groups.clear();
                    st.all_rows.clear();
                    st.rebuild();
                    st.sg_ids.clone()
                });
                if let Some(ids) = ids {
                    self.trigger_access_lens_fetch(event_tx, ids);
                }
            }
            // Go to the row's security group (closes the lens; Ctrl-O returns).
            KeyCode::Enter | KeyCode::Char('l') | KeyCode::Right => {
                let target = self
                    .access_in_pane
                    .as_ref()
                    .and_then(|st| st.selected_row())
                    .and_then(|row| row.jump_group());
                if let Some(id) = target {
                    self.close_access_lens();
                    self.record_location();
                    self.jump_to_cached_resource(
                        ServiceType::EC2,
                        id,
                        "Security Group",
                        false,
                        event_tx,
                    );
                }
            }
            // The whole merged table in $EDITOR.
            KeyCode::Char('e') | KeyCode::Char('v') => {
                if let Some(text) = self.access_in_pane.as_ref().map(|st| st.as_text()) {
                    self.pending_editor_content = Some((text, ".txt".to_string()));
                    self.editor_requested = true;
                }
            }
            KeyCode::Char('y') => {
                if let Some(text) = self
                    .access_in_pane
                    .as_ref()
                    .and_then(|st| st.selected_row())
                    .map(|row| row.text())
                {
                    self.copy_to_clipboard(&text, "rule");
                }
            }
            KeyCode::Char('Z') => {
                self.layout_mode = match self.layout_mode {
                    LayoutMode::DetailsOnly => LayoutMode::Split,
                    _ => LayoutMode::DetailsOnly,
                };
            }
            _ => {}
        }
    }

    /// Key handling while the CloudTrail lens owns the detail pane.
    fn handle_trail_lens_key(
        &mut self,
        key: crossterm::event::KeyEvent,
        event_tx: &mpsc::UnboundedSender<Event>,
    ) {
        use crossterm::event::{KeyCode, KeyModifiers};

        if let Some(st) = self.trail_in_pane.as_mut() {
            st.message = None;
        }
        let viewport = 20usize;

        match key.code {
            KeyCode::Esc | KeyCode::Char('q') | KeyCode::Char('W') => self.close_trail_lens(),
            KeyCode::Char('j') | KeyCode::Down => {
                if let Some(st) = self.trail_in_pane.as_mut() {
                    st.scroll_down(1);
                }
            }
            KeyCode::Char('k') | KeyCode::Up => {
                if let Some(st) = self.trail_in_pane.as_mut() {
                    st.scroll_up(1);
                }
            }
            KeyCode::Char('d') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                if let Some(st) = self.trail_in_pane.as_mut() {
                    st.scroll_down(viewport / 2);
                }
            }
            KeyCode::Char('u') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                if let Some(st) = self.trail_in_pane.as_mut() {
                    st.scroll_up(viewport / 2);
                }
            }
            KeyCode::PageDown => {
                if let Some(st) = self.trail_in_pane.as_mut() {
                    st.scroll_down(viewport);
                }
            }
            KeyCode::PageUp => {
                if let Some(st) = self.trail_in_pane.as_mut() {
                    st.scroll_up(viewport);
                }
            }
            KeyCode::Char('g') => {
                if let Some(st) = self.trail_in_pane.as_mut() {
                    st.goto_top();
                }
            }
            KeyCode::Char('G') => {
                if let Some(st) = self.trail_in_pane.as_mut() {
                    st.goto_bottom();
                }
            }
            // Narrow / widen the lookback window and re-run.
            KeyCode::Char('[') => {
                let changed = self.trail_in_pane.as_mut().is_some_and(|st| {
                    let n = st.range.narrower();
                    let changed = n != st.range;
                    st.range = n;
                    changed
                });
                if changed {
                    self.reseed_trail_lens(event_tx);
                }
            }
            KeyCode::Char(']') => {
                let changed = self.trail_in_pane.as_mut().is_some_and(|st| {
                    let w = st.range.wider();
                    let changed = w != st.range;
                    st.range = w;
                    changed
                });
                if changed {
                    self.reseed_trail_lens(event_tx);
                }
            }
            // Toggle read-only events in / out.
            KeyCode::Char('a') => {
                if let Some(st) = self.trail_in_pane.as_mut() {
                    st.include_reads = !st.include_reads;
                }
                self.reseed_trail_lens(event_tx);
            }
            KeyCode::Char('r') => self.reseed_trail_lens(event_tx),
            // Cycle the source filter: all → CT → ALM → CFN → DEP → all.
            KeyCode::Char('f') => {
                if let Some(st) = self.trail_in_pane.as_mut() {
                    st.cycle_source_filter();
                }
            }
            // Open the selected row in $EDITOR — raw JSON for CloudTrail
            // rows, a text summary for the other sources.
            KeyCode::Enter | KeyCode::Char('v') | KeyCode::Char('l') | KeyCode::Right => {
                if let Some((content, ext)) = self
                    .trail_in_pane
                    .as_ref()
                    .and_then(|st| st.selected_row())
                    .map(|row| {
                        if row.json.is_empty() {
                            (row.fallback_text(), ".txt".to_string())
                        } else {
                            (row.json.clone(), ".json".to_string())
                        }
                    })
                {
                    self.pending_editor_content = Some((content, ext));
                    self.editor_requested = true;
                }
            }
            // Copy the selected row (raw JSON, or the text summary).
            KeyCode::Char('y') => {
                if let Some(content) = self
                    .trail_in_pane
                    .as_ref()
                    .and_then(|st| st.selected_row())
                    .map(|row| {
                        if row.json.is_empty() {
                            row.fallback_text()
                        } else {
                            row.json.clone()
                        }
                    })
                {
                    self.copy_to_clipboard(&content, "timeline row");
                }
            }
            KeyCode::Char('Z') => {
                self.layout_mode = match self.layout_mode {
                    LayoutMode::DetailsOnly => LayoutMode::Split,
                    _ => LayoutMode::DetailsOnly};
            }
            _ => {}
        }
    }

    /// Key handling while the live tail / search pane owns the screen.
    fn handle_log_tail_key(
        &mut self,
        key: crossterm::event::KeyEvent,
        event_tx: &mpsc::UnboundedSender<Event>,
    ) {
        use crate::ui::widgets::log_tail::LogPaneMode;
        use crossterm::event::{KeyCode, KeyModifiers};
        self.log_tail.message = None;

        // Search-pattern input mode captures typing (Enter runs the search).
        if self.log_tail.query_active {
            match key.code {
                KeyCode::Esc => self.log_tail.query_active = false,
                KeyCode::Enter => {
                    self.log_tail.query_active = false;
                    self.run_log_search(event_tx);
                }
                KeyCode::Backspace => {
                    self.log_tail.query.pop();
                }
                KeyCode::Char(c) => self.log_tail.query.push(c),
                _ => {}
            }
            return;
        }

        // Search-mode key map (one-shot historical search).
        if self.log_tail.mode == LogPaneMode::Search {
            let viewport = 20usize;
            match key.code {
                KeyCode::Esc | KeyCode::Char('q') => self.close_log_tail(),
                KeyCode::Char('/') | KeyCode::Char('i') => self.log_tail.query_active = true,
                KeyCode::Enter => self.run_log_search(event_tx),
                KeyCode::Tab | KeyCode::Char('T') => {
                    self.log_tail.range = self.log_tail.range.cycle();
                    self.run_log_search(event_tx);
                }
                KeyCode::Char('j') | KeyCode::Down => self.log_tail.scroll_down(1, viewport),
                KeyCode::Char('k') | KeyCode::Up => self.log_tail.scroll_up(1),
                KeyCode::Char('d') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                    self.log_tail.scroll_down(10, viewport)
                }
                KeyCode::Char('u') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                    self.log_tail.scroll_up(10)
                }
                KeyCode::PageDown => self.log_tail.scroll_down(viewport, viewport),
                KeyCode::PageUp => self.log_tail.scroll_up(viewport),
                KeyCode::Char('g') => self.log_tail.goto_top(),
                KeyCode::Char('G') => self.log_tail.goto_bottom(),
                KeyCode::Char('y') => self.copy_log_tail_buffer(),
                KeyCode::Char('e') => self.edit_log_tail_buffer(),
                KeyCode::Char('w') => {
                    self.log_tail.wrap = !self.log_tail.wrap;
                    self.log_wrap = self.log_tail.wrap;
                }
                KeyCode::Char('Z') => {
                    self.layout_mode = match self.layout_mode {
                        LayoutMode::DetailsOnly => LayoutMode::Split,
                        _ => LayoutMode::DetailsOnly};
                }
                _ => {}
            }
            return;
        }

        // Filter input mode captures typing.
        if self.log_tail.filter_active {
            match key.code {
                KeyCode::Esc => {
                    self.log_tail.filter_active = false;
                    self.log_tail.filter.clear();
                }
                KeyCode::Enter => self.log_tail.filter_active = false,
                KeyCode::Backspace => {
                    self.log_tail.filter.pop();
                }
                KeyCode::Char(c) => self.log_tail.filter.push(c),
                _ => {}
            }
            return;
        }

        let viewport = 20usize; // approximate; scroll clamps against real len
        match key.code {
            KeyCode::Esc | KeyCode::Char('q') | KeyCode::Char('t') => self.close_log_tail(),
            KeyCode::Char('j') | KeyCode::Down => self.log_tail.scroll_down(1, viewport),
            KeyCode::Char('k') | KeyCode::Up => self.log_tail.scroll_up(1),
            KeyCode::Char('d') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                self.log_tail.scroll_down(10, viewport)
            }
            KeyCode::Char('u') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                self.log_tail.scroll_up(10)
            }
            KeyCode::PageDown => self.log_tail.scroll_down(viewport, viewport),
            KeyCode::PageUp => self.log_tail.scroll_up(viewport),
            KeyCode::Char('g') => self.log_tail.goto_top(),
            KeyCode::Char('G') => self.log_tail.goto_bottom(),
            KeyCode::Char('f') => {
                if self.log_tail.follow {
                    // Pause: freeze at the position actually on screen —
                    // `scroll` is stale while follow computes the top itself.
                    self.log_tail.follow = false;
                    self.log_tail.scroll = self.log_tail.render_top.get();
                } else {
                    self.log_tail.goto_bottom();
                }
            }
            // Narrow / widen the lookback window and re-seed (console-style).
            KeyCode::Char('[') => {
                let narrower = self.log_tail.range.narrower();
                if narrower != self.log_tail.range {
                    self.log_tail.range = narrower;
                    self.reseed_log_tail(event_tx);
                }
            }
            KeyCode::Char(']') => {
                let wider = self.log_tail.range.wider();
                if wider != self.log_tail.range {
                    self.log_tail.range = wider;
                    self.reseed_log_tail(event_tx);
                }
            }
            KeyCode::Char('/') => {
                self.log_tail.filter_active = true;
                self.log_tail.filter.clear();
            }
            // Flip the live tail into search mode on the same group (when known).
            KeyCode::Char('s') => {
                if self.log_tail.group.is_empty() {
                    self.log_tail.message =
                        Some("search not available for this source".to_string());
                } else {
                    self.log_tail_active
                        .store(false, std::sync::atomic::Ordering::Relaxed);
                    let group = self.log_tail.group.clone();
                    let streams = self.log_tail.streams.clone();
                    // Seed the pattern from the live substring filter, if any.
                    let seed = self.log_tail.filter.clone();
                    self.log_tail = crate::ui::widgets::log_tail::LogTailState::open_search(
                        format!("Search {}", group),
                        group,
                        streams,
                    );
                    self.log_tail.wrap = self.log_wrap;
                    self.log_tail.query = seed;
                    self.run_log_search(event_tx);
                }
            }
            KeyCode::Char('c') => {
                self.log_tail.lines.clear();
                self.log_tail.scroll = 0;
                self.log_tail.follow = true;
            }
            KeyCode::Char('y') => self.copy_log_tail_buffer(),
            // Open the current (filtered) buffer in $EDITOR to grep/save/etc.
            KeyCode::Char('e') => self.edit_log_tail_buffer(),
            // Wrap long lines instead of clipping at the pane edge. Sticky for
            // the session (config `log_wrap` sets the startup default).
            KeyCode::Char('w') => {
                self.log_tail.wrap = !self.log_tail.wrap;
                self.log_wrap = self.log_tail.wrap;
            }
            KeyCode::Char('Z') => {
                self.layout_mode = match self.layout_mode {
                    LayoutMode::DetailsOnly => LayoutMode::Split,
                    _ => LayoutMode::DetailsOnly};
            }
            _ => {}
        }
    }

    /// The current (in-buffer filtered) log lines as plain text, for copy/editor.
    fn log_tail_buffer_text(&self) -> String {
        self.log_tail
            .filtered()
            .iter()
            .map(|&i| {
                let l = &self.log_tail.lines[i];
                // Mirror the pane: a continuation row carries only its text, so
                // a copied stack trace keeps its own indentation.
                if l.continuation {
                    l.message.clone()
                } else if l.stream.is_empty() {
                    format!("{} {}", l.ts, l.message)
                } else {
                    format!("{} [{}] {}", l.ts, l.stream, l.message)
                }
            })
            .collect::<Vec<_>>()
            .join("\n")
    }

    fn copy_log_tail_buffer(&mut self) {
        let text = self.log_tail_buffer_text();
        if text.is_empty() {
            self.log_tail.message = Some("nothing to copy".to_string());
        } else {
            self.copy_to_clipboard(&text, "log lines");
            self.log_tail.message = Some("copied".to_string());
        }
    }

    fn edit_log_tail_buffer(&mut self) {
        let text = self.log_tail_buffer_text();
        if text.is_empty() {
            self.log_tail.message = Some("nothing to open".to_string());
        } else {
            self.pending_editor_content = Some((text, ".log".to_string()));
            self.editor_requested = true;
        }
    }

    /// Open the object browser for the selected bucket (root prefix).
    fn open_s3_object_browser(&mut self, event_tx: &mpsc::UnboundedSender<Event>) {
        if let Some(b) = self
            .get_selected_resource()
            .and_then(|r| r.as_any().downcast_ref::<crate::aws::services::s3::S3Bucket>())
        {
            let bucket = b.name.clone();
            let region = b.region.clone();
            // Fresh browse session → drop stale object metadata.
            self.lazy.s3_object_meta = Default::default();
            self.s3_object_browser.open(bucket, region);
            self.trigger_s3_objects_load(event_tx, false);
        }
    }

    /// The loaded metadata rows for the currently selected object, if cached.
    fn s3_selected_meta_rows(&self) -> Option<Vec<(String, String)>> {
        use crate::ui::widgets::s3_object_browser::S3ObjectBrowserState;
        let (key, version) = self.s3_object_browser.selected_entry()?.content_ref()?;
        let mk = S3ObjectBrowserState::meta_key(&self.s3_object_browser.bucket, key, version);
        match self.lazy.s3_object_meta.get(&mk)? {
            crate::lazy::Lazy::Loaded(meta) => Some(meta.rows()),
            _ => None}
    }

    /// Fetch the selected object's metadata for the info panel (lazy, cached by
    /// `bucket/key[@version]`). No-op unless the panel is open and an object
    /// (or a non-delete-marker version) is selected.
    fn trigger_s3_object_meta_load(&mut self, event_tx: &mpsc::UnboundedSender<Event>) {
        use crate::ui::widgets::s3_object_browser::S3ObjectBrowserState;
        if !self.s3_object_browser.show_detail {
            return;
        }
        let Some((key, version)) = self
            .s3_object_browser
            .selected_entry()
            .and_then(|e| e.content_ref())
        else {
            return;
        };
        let bucket = self.s3_object_browser.bucket.clone();
        let key = key.to_string();
        let version = version.map(str::to_string);
        let mk = S3ObjectBrowserState::meta_key(&bucket, &key, version.as_deref());
        let client = self.aws_clients.s3_client();
        self.trigger_lazy(
            |app| &mut app.lazy.s3_object_meta,
            mk,
            event_tx,
            async move {
                crate::aws::services::s3::fetch_s3_object_meta(client, bucket, key, version)
                    .await
                    .map(Box::new)
                    .map_err(|e| e.to_string())
            },
        );
    }

    /// List the current prefix (or fetch the next page when `append`).
    fn trigger_s3_objects_load(&mut self, event_tx: &mpsc::UnboundedSender<Event>, append: bool) {
        let st = &self.s3_object_browser;
        if st.bucket.is_empty() {
            return;
        }
        let bucket = st.bucket.clone();
        let prefix = st.prefix.clone();
        let token = if append { st.next_token.clone() } else { None };
        let recursive = st.recursive;
        let versions = st.versions;
        self.s3_object_browser.loading = true;
        self.s3_object_browser.error = None;
        let client = self.aws_clients.s3_client();
        let tx = event_tx.clone();
        tokio::spawn(async move {
            let result = if versions {
                crate::aws::services::s3::fetch_s3_object_versions(
                    client,
                    bucket.clone(),
                    prefix.clone(),
                    token,
                    recursive,
                )
                .await
            } else {
                crate::aws::services::s3::fetch_s3_objects(
                    client,
                    bucket.clone(),
                    prefix.clone(),
                    token,
                    recursive,
                )
                .await
            }
            .map_err(|e| e.to_string());
            let _ = tx.send(Event::S3ObjectsLoaded {
                bucket,
                prefix,
                result,
                append});
        });
    }

    /// Download the selected object (or object version) to the working directory.
    fn trigger_s3_object_download(&mut self, event_tx: &mpsc::UnboundedSender<Event>) {
        let st = &self.s3_object_browser;
        let Some((key, version)) = st.selected_entry().and_then(|e| e.content_ref()) else {
            self.s3_object_browser.message =
                Some("Select an object to download (delete markers have no content)".to_string());
            return;
        };
        let bucket = st.bucket.clone();
        let key = key.to_string();
        let version = version.map(str::to_string);
        self.s3_object_browser.message = Some(format!("Downloading {}…", basename(&key)));
        let client = self.aws_clients.s3_client();
        let tx = event_tx.clone();
        tokio::spawn(async move {
            let result = match crate::aws::services::s3::download_s3_object(
                client,
                bucket,
                key.clone(),
                version,
            )
            .await
            {
                Ok(bytes) => write_download(&key, &bytes).map_err(|e| e.to_string()),
                Err(e) => Err(e.to_string())};
            let _ = tx.send(Event::S3ObjectDownloaded { key, result });
        });
    }

    /// Generate a presigned GET URL (1h) for the selected object (or version)
    /// and copy it.
    fn trigger_s3_presign(&mut self, event_tx: &mpsc::UnboundedSender<Event>) {
        let st = &self.s3_object_browser;
        let Some((key, version)) = st.selected_entry().and_then(|e| e.content_ref()) else {
            self.s3_object_browser.message =
                Some("Select an object to presign (delete markers have no content)".to_string());
            return;
        };
        let bucket = st.bucket.clone();
        let key = key.to_string();
        let version = version.map(str::to_string);
        self.s3_object_browser.message = Some(format!("Presigning {}…", basename(&key)));
        let client = self.aws_clients.s3_client();
        let tx = event_tx.clone();
        tokio::spawn(async move {
            let result = crate::aws::services::s3::presign_s3_object(
                client,
                bucket,
                key.clone(),
                version,
                3600,
            )
            .await
            .map_err(|e| e.to_string());
            let _ = tx.send(Event::S3PresignedUrl { key, result });
        });
    }

    /// Fetch the selected object's text for inline view (`open_editor=false`) or
    /// `$EDITOR` (`open_editor=true`). Size-gated; binary content is refused.
    fn trigger_s3_object_open(
        &mut self,
        event_tx: &mpsc::UnboundedSender<Event>,
        open_editor: bool,
    ) {
        use crate::aws::services::s3::{fmt_object_size, S3Entry, PREVIEW_MAX_BYTES};
        let st = &self.s3_object_browser;
        let (key, version, size) = match st.selected_entry() {
            Some(S3Entry::Object { key, size, .. }) => (key.clone(), None, *size),
            Some(S3Entry::Version {
                key,
                version_id,
                delete_marker: false,
                size,
                ..
            }) => (key.clone(), Some(version_id.clone()), *size),
            Some(S3Entry::Version { delete_marker: true, .. }) => {
                self.s3_object_browser.message =
                    Some("Delete marker — no content to open".to_string());
                return;
            }
            _ => {
                self.s3_object_browser.message = Some("Select an object to open".to_string());
                return;
            }
        };
        let key = &key;
        // Editing a partial file is unsafe, so `e` still refuses oversize objects;
        // `v` previews the first 1 MiB of a large file (range GET) instead.
        let truncated = size > PREVIEW_MAX_BYTES;
        if truncated && open_editor {
            self.s3_object_browser.message = Some(format!(
                "{} is too large to edit ({}) — press d to download",
                basename(key),
                fmt_object_size(size),
            ));
            return;
        }
        let bucket = st.bucket.clone();
        let key = key.clone();
        self.s3_object_browser.message = Some(format!("Loading {}…", basename(&key)));
        let client = self.aws_clients.s3_client();
        let tx = event_tx.clone();
        tokio::spawn(async move {
            let bytes = if truncated {
                crate::aws::services::s3::download_s3_object_range(
                    client,
                    bucket.clone(),
                    key.clone(),
                    version,
                    PREVIEW_MAX_BYTES,
                )
                .await
            } else {
                crate::aws::services::s3::download_s3_object(
                    client,
                    bucket.clone(),
                    key.clone(),
                    version,
                )
                .await
            };
            let result = match bytes {
                Ok(bytes) => match crate::aws::services::s3::decode_text_preview(&bytes, truncated) {
                    Some(text) if truncated => Ok(format!(
                        "// showing first {} of {} — press d to download the full object\n\n{}",
                        fmt_object_size(PREVIEW_MAX_BYTES),
                        fmt_object_size(size),
                        text
                    )),
                    Some(text) => Ok(text),
                    None => Err("binary content — press d to download instead".to_string())},
                Err(e) => Err(e.to_string())};
            let _ = tx.send(Event::S3ObjectContentLoaded { key, result });
        });
    }

    fn bookmark_s3_object(&mut self) {
        let st = &self.s3_object_browser;
        let Some(entry) = st.selected_entry() else {
            self.s3_object_browser.message = Some("Nothing to bookmark".to_string());
            return;
        };
        let key = entry.full_path().to_string();
        let bucket = st.bucket.clone();
        let basename = key.rsplit('/').next().unwrap_or(&key).to_string();

        // Check if already bookmarked
        if let Some(pos) = self.bookmarks.iter().position(|b| {
            b.s3_object_path.as_ref() == Some(&(bucket.clone(), key.clone()))
        }) {
            self.bookmarks.remove(pos);
            self.s3_object_browser.message = Some("Bookmark removed".to_string());
        } else {
            let loc = NavLocation {
                service: ServiceType::S3,
                view: JumpView::None,
                query: String::new(),
                selected_id: Some(bucket.clone()),
                label: format!("S3 · s3://{}/{}", bucket, basename),
                s3_object_path: Some((bucket, key)),
                details_focused: false,
                detail_section: None};
            self.bookmarks.push(loc);
            self.s3_object_browser.message = Some("Bookmarked".to_string());
        }
        crate::bookmarks::save(&self.bookmarks);
    }

    fn trigger_s3_tfstate_open(&mut self, event_tx: &mpsc::UnboundedSender<Event>) {
        let st = &self.s3_object_browser;
        let Some((key, version)) = st.selected_entry().and_then(|e| e.content_ref()) else {
            self.s3_object_browser.message = Some("Select a .tfstate file".to_string());
            return;
        };
        if !key.ends_with(".tfstate") && !key.ends_with(".tfstate.backup") {
            self.s3_object_browser.message = Some("Not a .tfstate file".to_string());
            return;
        }
        let bucket = st.bucket.clone();
        let key = key.to_string();
        let version = version.map(str::to_string);
        self.s3_object_browser.message = Some("Loading terraform state…".to_string());
        let client = self.aws_clients.s3_client();
        let tx = event_tx.clone();
        tokio::spawn(async move {
            let bytes =
                crate::aws::services::s3::download_s3_object(client, bucket, key, version).await;
            let result = match bytes {
                Ok(bytes) => match String::from_utf8(bytes) {
                    Ok(text) => crate::terraform::parse_tfstate(&text).map_err(|e| e.to_string()),
                    Err(_) => Err("State file is not valid UTF-8".to_string())},
                Err(e) => Err(e.to_string())};
            let _ = tx.send(Event::TfStateLoaded { result });
        });
    }

    /// All key handling for the S3 object browser overlay.
    fn handle_s3_object_browser_key(
        &mut self,
        key: crossterm::event::KeyEvent,
        event_tx: &mpsc::UnboundedSender<Event>,
    ) {
        use crate::aws::services::s3::S3Entry;
        use crossterm::event::{KeyCode, KeyModifiers};

        // Half-page / full-page jumps (the visible window is roughly this tall).
        const HALF_PAGE: usize = 15;
        const PAGE: usize = 30;

        // `?` toggles the help cheat-sheet from anywhere.
        if key.code == KeyCode::Char('?') && !self.s3_object_browser.filtering {
            self.s3_object_browser.show_help = !self.s3_object_browser.show_help;
            return;
        }
        if self.s3_object_browser.show_help {
            if matches!(key.code, KeyCode::Esc | KeyCode::Char('?')) {
                self.s3_object_browser.show_help = false;
            }
            return;
        }

        // Filter-input mode: typing edits the filter string.
        if self.s3_object_browser.filtering {
            match key.code {
                KeyCode::Esc => {
                    self.s3_object_browser.filter.clear();
                    self.s3_object_browser.filtering = false;
                    self.s3_object_browser.selected = 0;
                }
                KeyCode::Enter | KeyCode::Down => {
                    self.s3_object_browser.filtering = false;
                }
                KeyCode::Backspace => {
                    self.s3_object_browser.filter.pop();
                    self.s3_object_browser.selected = 0;
                }
                KeyCode::Char(c) => {
                    self.s3_object_browser.filter.push(c);
                    self.s3_object_browser.selected = 0;
                }
                _ => {}
            }
            return;
        }

        // Metadata panel focused: navigate its rows and copy values.
        if self.s3_object_browser.show_detail && self.s3_object_browser.detail_focus {
            let rows = self.s3_selected_meta_rows();
            let n = rows.as_ref().map(|r| r.len()).unwrap_or(0);
            match key.code {
                KeyCode::Esc | KeyCode::Tab | KeyCode::Char('h') | KeyCode::Left => {
                    self.s3_object_browser.detail_focus = false;
                }
                KeyCode::Char('q') => self.s3_object_browser.close(),
                KeyCode::Up | KeyCode::Char('k') => {
                    if self.s3_object_browser.detail_selected > 0 {
                        self.s3_object_browser.detail_selected -= 1;
                    }
                }
                KeyCode::Down | KeyCode::Char('j') => {
                    if self.s3_object_browser.detail_selected + 1 < n {
                        self.s3_object_browser.detail_selected += 1;
                    }
                }
                KeyCode::Char('y') => {
                    if let Some(rows) = &rows {
                        if let Some((k, v)) = rows.get(self.s3_object_browser.detail_selected) {
                            let (k, v) = (k.clone(), v.clone());
                            self.copy_to_clipboard(&v, &k);
                            self.s3_object_browser.message = Some(format!("Copied {}", k));
                        }
                    }
                }
                KeyCode::Char('Y') => {
                    if let Some(rows) = &rows {
                        let text = rows
                            .iter()
                            .map(|(k, v)| format!("{}: {}", k, v))
                            .collect::<Vec<_>>()
                            .join("\n");
                        self.copy_to_clipboard(&text, "metadata");
                        self.s3_object_browser.message = Some("Copied all metadata".to_string());
                    }
                }
                _ => {}
            }
            return;
        }

        match key.code {
            KeyCode::Esc | KeyCode::Char('q') => {
                if !self.s3_object_browser.filter.is_empty() {
                    self.s3_object_browser.filter.clear();
                    self.s3_object_browser.selected = 0;
                } else {
                    self.s3_object_browser.close();
                }
            }
            KeyCode::Tab => {
                // Open (if needed) and focus the metadata panel for copying.
                self.s3_object_browser.show_detail = true;
                self.s3_object_browser.detail_focus = true;
                self.s3_object_browser.detail_selected = 0;
                self.s3_object_browser.message = None;
            }
            KeyCode::Char('Z') => {
                // Toggle the detail pane between full-width and split (list visible).
                self.layout_mode = match self.layout_mode {
                    LayoutMode::DetailsOnly => LayoutMode::Split,
                    _ => LayoutMode::DetailsOnly};
            }
            KeyCode::Up | KeyCode::Char('k') => {
                self.s3_object_browser.message = None;
                if self.s3_object_browser.selected > 0 {
                    self.s3_object_browser.selected -= 1;
                }
            }
            KeyCode::Down | KeyCode::Char('j') => {
                self.s3_object_browser.message = None;
                let n = self.s3_object_browser.filtered_indices().len();
                if self.s3_object_browser.selected + 1 < n {
                    self.s3_object_browser.selected += 1;
                }
            }
            KeyCode::Char('d') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                self.s3_object_browser.move_selection(HALF_PAGE as isize);
            }
            KeyCode::Char('u') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                self.s3_object_browser.move_selection(-(HALF_PAGE as isize));
            }
            KeyCode::PageDown => self.s3_object_browser.move_selection(PAGE as isize),
            KeyCode::PageUp => self.s3_object_browser.move_selection(-(PAGE as isize)),
            KeyCode::Char('g') => self.s3_object_browser.selected = 0,
            KeyCode::Char('G') => {
                let n = self.s3_object_browser.filtered_indices().len();
                self.s3_object_browser.selected = n.saturating_sub(1);
            }
            KeyCode::Enter | KeyCode::Char('l') | KeyCode::Right => {
                match self.s3_object_browser.selected_entry().cloned() {
                    Some(S3Entry::Folder { prefix }) => {
                        self.s3_object_browser.set_prefix(prefix);
                        self.trigger_s3_objects_load(event_tx, false);
                    }
                    Some(S3Entry::Object { .. }) | Some(S3Entry::Version { .. }) => {
                        // A delete-marker row gets its explanatory message
                        // from the trigger itself.
                        self.trigger_s3_object_open(event_tx, false);
                    }
                    None => {}
                }
            }
            KeyCode::Char('h') | KeyCode::Left | KeyCode::Backspace => {
                if let Some(parent) = self.s3_object_browser.parent_prefix() {
                    self.s3_object_browser.set_prefix(parent);
                    self.trigger_s3_objects_load(event_tx, false);
                }
            }
            KeyCode::Char('i') => {
                self.s3_object_browser.show_detail = !self.s3_object_browser.show_detail;
                if !self.s3_object_browser.show_detail {
                    self.s3_object_browser.detail_focus = false;
                }
                self.s3_object_browser.message = None;
            }
            KeyCode::Char('/') => {
                self.s3_object_browser.filtering = true;
                self.s3_object_browser.message = None;
            }
            KeyCode::Char('f') => {
                // Toggle recursive (flat, everything-under-prefix) listing.
                let b = &mut self.s3_object_browser;
                b.recursive = !b.recursive;
                b.entries.clear();
                b.selected = 0;
                b.next_token = None;
                b.filter.clear();
                b.message = Some(if b.recursive {
                    "Recursive: listing all objects under this prefix".to_string()
                } else {
                    "Folder view".to_string()
                });
                self.trigger_s3_objects_load(event_tx, false);
            }
            KeyCode::Char('V') => {
                // Toggle version history (every version + delete marker via
                // ListObjectVersions) for the current prefix.
                let b = &mut self.s3_object_browser;
                b.versions = !b.versions;
                b.entries.clear();
                b.selected = 0;
                b.next_token = None;
                b.filter.clear();
                b.message = Some(if b.versions {
                    "Versions: listing all versions + delete markers".to_string()
                } else {
                    "Current objects".to_string()
                });
                self.trigger_s3_objects_load(event_tx, false);
            }
            KeyCode::Char('s') => {
                let b = &mut self.s3_object_browser;
                b.sort_field = b.sort_field.next();
                b.apply_sort();
                b.message = Some(format!("Sorted by {}", b.sort_indicator()));
            }
            KeyCode::Char('S') => {
                let b = &mut self.s3_object_browser;
                b.sort_desc = !b.sort_desc;
                b.apply_sort();
                b.message = Some(format!("Sorted by {}", b.sort_indicator()));
            }
            KeyCode::Char('n') => {
                if self.s3_object_browser.next_token.is_some() && !self.s3_object_browser.loading {
                    self.trigger_s3_objects_load(event_tx, true);
                }
            }
            KeyCode::Char('d') => self.trigger_s3_object_download(event_tx),
            KeyCode::Char('p') => self.trigger_s3_presign(event_tx),
            KeyCode::Char('v') => self.trigger_s3_object_open(event_tx, false),
            KeyCode::Char('e') => self.trigger_s3_object_open(event_tx, true),
            KeyCode::Char('t') => self.trigger_s3_tfstate_open(event_tx),
            KeyCode::Char('B') => self.bookmark_s3_object(),
            KeyCode::Char('y') => {
                if let Some(err) = self.s3_object_browser.error.clone() {
                    self.copy_to_clipboard(&err, "error");
                    self.s3_object_browser.message = Some("Copied error".to_string());
                } else if let Some(e) = self.s3_object_browser.selected_entry() {
                    let uri = format!("s3://{}/{}", self.s3_object_browser.bucket, e.full_path());
                    self.s3_object_browser.message = Some(format!("Copied {}", uri));
                    self.copy_to_clipboard(&uri, "S3 URI");
                }
            }
            _ => {}
        }

        // Keep the info panel in sync with the current selection (movement,
        // toggle, descend) — lazy + cached, so this is a no-op when closed or
        // already fetched.
        self.trigger_s3_object_meta_load(event_tx);
    }

    pub(crate) fn trigger_config_eval_load(&mut self, event_tx: &mpsc::UnboundedSender<Event>) {
        if let Some(rule) = self.get_selected_resource().and_then(|r| {
            r.as_any()
                .downcast_ref::<crate::aws::services::awsconfig::ConfigRule>()
        }) {
            let rule_name = rule.name.clone();
            let client = self.aws_clients.awsconfig_client();
            self.trigger_lazy(
                |app| &mut app.lazy.config_eval,
                rule_name.clone(),
                event_tx,
                async move {
                    crate::aws::services::awsconfig::fetch_noncompliant_resources(client, rule_name)
                        .await
                        .map_err(|e| format!("Non-compliant resources unavailable: {}", e))
                },
            );
        }
    }

    /// Trigger a lazy-load of attached managed/inline policies for the selected role.
    pub(crate) fn trigger_iam_role_details_load(&mut self, event_tx: &mpsc::UnboundedSender<Event>) {
        if let Some(role) = self
            .get_selected_resource()
            .and_then(|r| r.as_any().downcast_ref::<crate::aws::services::iam::IamRole>())
        {
            let role_name = role.role_name.clone();
            let client = self.aws_clients.iam_client();
            self.trigger_lazy(
                |app| &mut app.lazy.iam_role_details,
                role_name.clone(),
                event_tx,
                async move {
                    crate::aws::services::iam::fetch_iam_role_details(client, role_name)
                        .await
                        .map_err(|e| format!("Role details unavailable: {}", e))
                },
            );
        }
    }

    /// Lazy-load a user's access keys / MFA / groups / policies, keyed by name.
    pub(crate) fn trigger_iam_user_details_load(&mut self, event_tx: &mpsc::UnboundedSender<Event>) {
        if let Some(user) = self
            .get_selected_resource()
            .and_then(|r| r.as_any().downcast_ref::<crate::aws::services::iam::IamUser>())
        {
            let user_name = user.user_name.clone();
            let client = self.aws_clients.iam_client();
            self.trigger_lazy(
                |app| &mut app.lazy.iam_user_details,
                user_name.clone(),
                event_tx,
                async move {
                    crate::aws::services::iam::fetch_iam_user_details(client, user_name)
                        .await
                        .map_err(|e| format!("User details unavailable: {}", e))
                },
            );
        }
    }

    /// Lazy-load a group's members + policies, keyed by group name.
    pub(crate) fn trigger_iam_group_details_load(&mut self, event_tx: &mpsc::UnboundedSender<Event>) {
        if let Some(group) = self
            .get_selected_resource()
            .and_then(|r| r.as_any().downcast_ref::<crate::aws::services::iam::IamGroup>())
        {
            let group_name = group.group_name.clone();
            let client = self.aws_clients.iam_client();
            self.trigger_lazy(
                |app| &mut app.lazy.iam_group_details,
                group_name.clone(),
                event_tx,
                async move {
                    crate::aws::services::iam::fetch_iam_group_details(client, group_name)
                        .await
                        .map_err(|e| format!("Group details unavailable: {}", e))
                },
            );
        }
    }

