    /// `s` on an Organizations account row: assume the configured org access
    /// role in that member account (always a ReadOnlyAccess-scoped session).
    /// Returns true when the key was consumed (an OrgAccount is selected),
    /// even if the switch is refused — a suspended account or the account
    /// already being browsed gets a status message, not an SSM session menu.
    fn trigger_org_role_switch(&mut self, event_tx: &mpsc::UnboundedSender<Event>) -> bool {
        let target = self
            .get_selected_resource()
            .and_then(|r| {
                r.as_any()
                    .downcast_ref::<crate::aws::services::organizations::OrgAccount>()
            })
            .map(|a| (a.account_id.clone(), a.account_name.clone(), a.status.clone()));
        let Some((account_id, account_name, status)) = target else {
            return false;
        };
        if self.account_id.as_deref() == Some(account_id.as_str()) {
            self.error_message = Some(format!("Already browsing account {}", account_id));
            return true;
        }
        if status != "ACTIVE" {
            self.error_message = Some(format!(
                "Account {} is {} — cannot assume a role in it",
                account_id, status
            ));
            return true;
        }
        // Several configured roles → pick one (last-used preselected);
        // a single role fires directly.
        if self.org_access_roles.len() > 1 {
            self.org_role_selector.show(
                &self.org_access_roles,
                &self.org_access_role,
                account_id,
                account_name,
            );
            return true;
        }
        let _ = event_tx.send(Event::OrgRoleSwitchRequested {
            account_id,
            account_name,
            role_name: self.org_access_roles[0].clone()});
        true
    }

