    /// Pick a sensible initial overlay range for the selected alarm: the
    /// smallest range whose window can hold at least one full evaluation
    /// period, so an alarm with a long period (e.g. 5h) doesn't open on an
    /// empty 1h chart. Capped at 7 days.
    fn default_alarm_metrics_range(&self) -> MetricsTimeRange {
        let period = self
            .get_selected_resource()
            .and_then(|r| r.as_any().downcast_ref::<crate::aws::services::cloudwatch::CwAlarm>())
            .map(|a| a.period as i64)
            .unwrap_or(0);
        if period <= MetricsTimeRange::OneHour.duration_secs() {
            MetricsTimeRange::OneHour
        } else if period <= MetricsTimeRange::SixHours.duration_secs() {
            MetricsTimeRange::SixHours
        } else if period <= MetricsTimeRange::TwentyFourHours.duration_secs() {
            MetricsTimeRange::TwentyFourHours
        } else {
            MetricsTimeRange::SevenDays
        }
    }

    /// Fetch the selected alarm's own metric series for the metric-chart
    /// overlay. Always refetches (cheap, time-windowed) so `[`/`]`/`r` reflect
    /// the current range. No-op when the selection isn't a CwAlarm.
    fn trigger_cw_alarm_metrics_load(&mut self, event_tx: &mpsc::UnboundedSender<Event>) {
        if let Some(alarm) = self
            .get_selected_resource()
            .and_then(|r| r.as_any().downcast_ref::<crate::aws::services::cloudwatch::CwAlarm>())
        {
            let alarm_arn = alarm.alarm_arn.clone();
            let namespace = alarm.namespace.clone();
            let metric_name = alarm.metric_name.clone();
            let dimensions = alarm.dimensions.clone();
            let statistic = alarm.statistic.clone();
            let period = alarm.period;
            let threshold = alarm.threshold;
            let time_range = self.cw_alarm_metrics_time_range;
            self.cw_alarm_metrics
                .insert(alarm_arn.clone(), CwAlarmMetricsState::Loading);
            let client = self.aws_clients.cloudwatch_client();
            let tx = event_tx.clone();
            tokio::spawn(async move {
                match crate::aws::services::cloudwatch::fetch_alarm_metrics(
                    client,
                    namespace,
                    metric_name,
                    dimensions,
                    statistic,
                    period,
                    threshold,
                    time_range,
                )
                .await
                {
                    Ok(data) => {
                        let _ = tx.send(crate::event::Event::CwAlarmMetricsLoaded { alarm_arn, data });
                    }
                    Err(e) => {
                        let _ = tx.send(crate::event::Event::ResourceLoadError {
                            service: crate::aws::service::ServiceType::CloudWatch,
                            error: format!("Failed to load alarm metric: {}", e)});
                    }
                }
            });
        } else if let Some(metric) = self
            .get_selected_resource()
            .and_then(|r| r.as_any().downcast_ref::<crate::aws::services::cloudwatch::CwMetric>())
        {
            // Metric explorer: chart the raw metric (Average, no threshold line).
            let key = metric.id.clone();
            let namespace = metric.namespace.clone();
            let metric_name = metric.metric_name.clone();
            let dimensions = metric.dimensions.clone();
            let time_range = self.cw_alarm_metrics_time_range;
            self.cw_alarm_metrics
                .insert(key.clone(), CwAlarmMetricsState::Loading);
            let client = self.aws_clients.cloudwatch_client();
            let tx = event_tx.clone();
            tokio::spawn(async move {
                match crate::aws::services::cloudwatch::fetch_alarm_metrics(
                    client,
                    namespace,
                    metric_name,
                    dimensions,
                    "Average".to_string(),
                    60,
                    0.0,
                    time_range,
                )
                .await
                {
                    Ok(data) => {
                        let _ = tx.send(crate::event::Event::CwAlarmMetricsLoaded {
                            alarm_arn: key,
                            data});
                    }
                    Err(e) => {
                        let _ = tx.send(crate::event::Event::ResourceLoadError {
                            service: crate::aws::service::ServiceType::CloudWatch,
                            error: format!("Failed to load metric: {}", e)});
                    }
                }
            });
        }
    }

