    /// Lazily fetch the metric-explorer metric list (ListMetrics) the first time
    /// the Metrics sub-tab is shown, grafting the results into the resource list.
    /// Skips if already loading or the metrics are already present.
    fn trigger_cw_metrics_load(&mut self, event_tx: &mpsc::UnboundedSender<Event>) {
        if self.cw_metrics_loading {
            return;
        }
        if self
            .resources
            .iter()
            .any(|r| r.resource_type() == "CW Metric")
        {
            return;
        }
        self.cw_metrics_loading = true;
        let client = self.aws_clients.cloudwatch_client();
        let tx = event_tx.clone();
        tokio::spawn(async move {
            match crate::aws::services::cloudwatch::fetch_metrics(client).await {
                Ok((metrics, capped)) => {
                    let _ = tx.send(crate::event::Event::CwMetricsLoaded { metrics, capped });
                }
                Err(e) => {
                    let _ = tx.send(crate::event::Event::CwMetricsLoaded {
                        metrics: Vec::new(),
                        capped: false});
                    let _ = tx.send(crate::event::Event::ResourceLoadError {
                        service: crate::aws::service::ServiceType::CloudWatch,
                        error: format!("Failed to list metrics: {}", e)});
                }
            }
        });
    }

