    /// `e` on a log-file entry in the instance Logs section: download the
    /// file's tail and open it in `$EDITOR` (the fetch stashes content via
    /// `CwLogInsightsLoaded`). The cursor may sit on the "Log File" row or on
    /// its dim size/date annotation line — both resolve to the same file.
    /// Returns false when the cursor isn't on a log entry so `e` falls
    /// through to the default editor path.
    fn trigger_rds_log_file_fetch(&mut self, event_tx: &mpsc::UnboundedSender<Event>) -> bool {
        if !self.details_focused {
            return false;
        }
        let Some(db_id) = self
            .get_selected_resource()
            .and_then(|r| {
                r.as_any()
                    .downcast_ref::<crate::aws::services::rds::RdsInstance>()
            })
            .map(|db| db.db_identifier.clone())
        else {
            return false;
        };
        if crate::aws::services::rds::RdsInstanceDetailSection::from_index(self.detail_section_idx)
            != crate::aws::services::rds::RdsInstanceDetailSection::Logs
        {
            return false;
        }
        let Some(idx) = self.details_selected_index else {
            return false;
        };
        let rows = self.get_detail_lines_filtered();
        let file_row = |(key, value): &(String, String)| -> Option<String> {
            (key.trim_start() == "Log File" && !value.is_empty()).then(|| value.clone())
        };
        let Some(file_name) = rows.get(idx).and_then(|row| {
            file_row(row).or_else(|| {
                // The annotation line under a file row ("    · 12 KiB · …")
                // resolves to the file above it.
                if row.0.trim_start().starts_with('·') && row.1.is_empty() {
                    rows[..idx].iter().rev().find_map(file_row)
                } else {
                    None
                }
            })
        }) else {
            return false;
        };

        self.success_message = Some(format!("Downloading {}…", file_name));
        self.success_message_time = Some(Instant::now());
        let client = self.aws_clients.rds_client();
        let tx = event_tx.clone();
        tokio::spawn(async move {
            match crate::aws::services::rds::fetch_rds_log_tail(client, db_id, file_name).await {
                Ok(content) => {
                    let _ = tx.send(Event::CwLogInsightsLoaded { content });
                }
                Err(e) => {
                    let _ = tx.send(Event::ResourceLoadError {
                        service: crate::aws::service::ServiceType::RDS,
                        error: format!("Failed to download log file: {}", e),
                    });
                }
            }
        });
        true
    }

