    /// Rebuild the Inspector service with the current severity scope and reload.
    fn apply_insp_severity_scope(&mut self) {
        self.services.insert(
            ServiceType::Inspector,
            Arc::new(crate::aws::services::inspector::InspectorService::new(
                &self.aws_clients,
                self.insp_severity_scope,
            )),
        );
        self.load_service_resources();
        self.update_search();
    }

    /// Rebuild the Cost service with the current group-by/period and reload.
    /// The variant-keyed cache means a previously-viewed combination is served
    /// from cache instantly; only a genuinely new combination refetches.
    fn apply_cost_query(&mut self) {
        let query = crate::aws::services::cost::CostQuery {
            group_by: self.cost_group_by,
            period: self.cost_period};
        self.services.insert(
            ServiceType::Cost,
            Arc::new(crate::aws::services::cost::CostService::with_query(
                &self.aws_clients,
                query,
            )),
        );
        self.load_service_resources();
        // Rebuild the filtered list + clamp selection for the new grouping. On a
        // cache hit `load_service_resources` swaps `resources` but returns before
        // re-filtering, leaving stale (possibly out-of-bounds) indices behind;
        // on a cache miss this filters the now-empty list and the streaming
        // events re-filter as data arrives.
        self.update_search();
    }

    /// Rebuild the Service Quotas service scoped to the current service code and
    /// reload. Variant-cached by code, so switching back is instant.
    fn apply_quota_service_code(&mut self) {
        self.services.insert(
            ServiceType::ServiceQuotas,
            Arc::new(
                crate::aws::services::service_quotas::ServiceQuotasService::with_code(
                    &self.aws_clients,
                    self.quota_service_code.clone(),
                ),
            ),
        );
        self.load_service_resources();
        self.update_search();
    }

    /// Fetch the full ListServices catalogue for the picker (once per session).
    fn trigger_quota_services_load(&mut self, event_tx: &mpsc::UnboundedSender<Event>) {
        if !self.quota_services.is_empty() {
            return;
        }
        let client = self.aws_clients.service_quotas_client();
        let tx = event_tx.clone();
        tokio::spawn(async move {
            if let Ok(services) =
                crate::aws::services::service_quotas::fetch_quota_services(client).await
            {
                let _ = tx.send(crate::event::Event::QuotaServicesLoaded { services });
            }
        });
    }

