    /// Fetch the selected runtime's A2A agent card. Fired **only** from the
    /// explicit `x` reveal while the Agent Card section is open — never from a
    /// section hook, because the call reaches the agent container (see
    /// `agentcore::fetch_agent_card`).
    fn trigger_agentcore_agent_card_load(&mut self, event_tx: &mpsc::UnboundedSender<Event>) {
        use crate::aws::services::agentcore::AgentCoreRuntimeDetailSection as S;
        if S::from_index(self.detail_section_idx) != S::AgentCard {
            return;
        }
        let Some(r) = self.get_selected_resource().and_then(|r| {
            r.as_any()
                .downcast_ref::<crate::aws::services::agentcore::AgentCoreRuntime>()
        }) else {
            return;
        };
        let (id, arn) = (r.runtime_id.clone(), r.arn.clone());
        let dp = self.aws_clients.agentcore_client();
        self.trigger_lazy(
            |app| &mut app.lazy.agentcore_agent_card,
            id,
            event_tx,
            async move {
                crate::aws::services::agentcore::fetch_agent_card(dp, arn, None)
                    .await
                    .map_err(|e| format!("Agent card unavailable: {}", e))
            },
        );
    }

    /// Whether `x` fetches an agent card here — the runtime's Agent Card
    /// section, focused, and not already fetched.
    fn agentcore_agent_card_pending(&self) -> bool {
        use crate::aws::services::agentcore::AgentCoreRuntimeDetailSection as S;
        if S::from_index(self.detail_section_idx) != S::AgentCard {
            return false;
        }
        self.get_selected_resource()
            .and_then(|r| {
                r.as_any()
                    .downcast_ref::<crate::aws::services::agentcore::AgentCoreRuntime>()
            })
            .map(|r| !self.lazy.agentcore_agent_card.contains(&r.runtime_id))
            .unwrap_or(false)
    }

