    /// `GetResourcePolicy` on a runtime or gateway — the only two types the
    /// API supports. Keyed by resource id; the ARN is the lookup argument.
    ///
    /// The gateway has no eager ARN (`ListGateways` returns none), so it falls
    /// back to synthesizing one the same way the metrics overlay does. In
    /// practice the lazy `GetGateway` bundle has already landed: Overview is
    /// section 0 and drill-in always fires its hook. Nothing is triggered when
    /// no ARN can be resolved at all — inserting a `Loading` we can never
    /// resolve, or an error the contains-guard would cache for the session,
    /// are both worse than leaving the key absent so the next visit retries.
    pub(crate) fn trigger_agentcore_resource_policy_load(
        &mut self,
        event_tx: &mpsc::UnboundedSender<Event>,
    ) {
        use crate::aws::services::agentcore::{AgentCoreGateway, AgentCoreRuntime};
        let ctl = self.aws_clients.agentcore_control_client();
        let target = self.get_selected_resource().and_then(|r| {
            let a = r.as_any();
            if let Some(rt) = a.downcast_ref::<AgentCoreRuntime>() {
                return Some((rt.runtime_id.clone(), rt.arn.clone()));
            }
            let g = a.downcast_ref::<AgentCoreGateway>()?;
            if let Some(crate::lazy::Lazy::Loaded(d)) =
                self.lazy.agentcore_gateway_detail.get(&g.gateway_id)
            {
                if !d.arn.is_empty() {
                    return Some((g.gateway_id.clone(), d.arn.clone()));
                }
            }
            let account = self.account_id.as_ref()?;
            Some((
                g.gateway_id.clone(),
                format!(
                    "arn:aws:bedrock-agentcore:{}:{}:gateway/{}",
                    self.current_region.as_str(),
                    account,
                    g.gateway_id
                ),
            ))
        });
        if let Some((key, arn)) = target {
            if arn.is_empty() {
                return;
            }
            self.trigger_lazy(
                |app| &mut app.lazy.agentcore_resource_policy,
                key,
                event_tx,
                async move {
                    crate::aws::services::agentcore::fetch_resource_policy(ctl, arn)
                        .await
                        .map_err(|e| format!("Resource policy unavailable: {}", e))
                },
            );
        }
    }

    /// One hook for all three Identity families. Each `Get*` keys off name;
    /// the map keys off ARN, because the three name spaces are independent.
    pub(crate) fn trigger_agentcore_identity_detail_load(
        &mut self,
        event_tx: &mpsc::UnboundedSender<Event>,
    ) {
        use crate::aws::services::agentcore::{
            AgentCoreApiKeyProvider, AgentCoreOAuth2Provider, AgentCoreWorkloadIdentity,
        };
        #[derive(Clone, Copy)]
        enum Kind {
            Workload,
            OAuth2,
            ApiKey,
        }
        let ctl = self.aws_clients.agentcore_control_client();
        let target = self.get_selected_resource().and_then(|r| {
            let a = r.as_any();
            if let Some(w) = a.downcast_ref::<AgentCoreWorkloadIdentity>() {
                Some((w.arn.clone(), w.name.clone(), Kind::Workload))
            } else if let Some(o) = a.downcast_ref::<AgentCoreOAuth2Provider>() {
                Some((o.arn.clone(), o.name.clone(), Kind::OAuth2))
            } else {
                a.downcast_ref::<AgentCoreApiKeyProvider>()
                    .map(|k| (k.arn.clone(), k.name.clone(), Kind::ApiKey))
            }
        });
        if let Some((key, name, kind)) = target {
            self.trigger_lazy(
                |app| &mut app.lazy.agentcore_identity_detail,
                key,
                event_tx,
                async move {
                    use crate::aws::services::agentcore as ac;
                    let r = match kind {
                        Kind::Workload => ac::fetch_workload_identity_detail(ctl, name).await,
                        Kind::OAuth2 => ac::fetch_oauth2_provider_detail(ctl, name).await,
                        Kind::ApiKey => ac::fetch_api_key_provider_detail(ctl, name).await,
                    };
                    r.map(Box::new)
                        .map_err(|e| format!("Identity detail unavailable: {}", e))
                },
            );
        }
    }

    /// The Secret section needs both the provider's own detail (for the secret
    /// ARN) and the token vault protecting it, so its hook fires both. Both
    /// are contains-guarded, so firing twice is free.
    pub(crate) fn trigger_agentcore_identity_secret_load(
        &mut self,
        event_tx: &mpsc::UnboundedSender<Event>,
    ) {
        self.trigger_agentcore_identity_detail_load(event_tx);
        self.trigger_agentcore_token_vault_load(event_tx);
    }

