    fn trigger_waf_sampled_requests_fetch(
        &self,
        event_tx: &mpsc::UnboundedSender<Event>,
    ) -> bool {
        if let Some(acl) = self.get_selected_resource().and_then(|r| {
            r.as_any()
                .downcast_ref::<crate::aws::services::waf::WafWebAcl>()
        }) {
            let arn = acl.arn.clone();
            let name = acl.name.clone();
            let id = acl.id.clone();
            let scope = self.waf_scope;
            let client = match scope {
                WafScope::CloudFront => self.aws_clients.wafv2_cloudfront_client(),
                WafScope::Regional => self.aws_clients.wafv2_client()};
            let tx = event_tx.clone();
            tokio::spawn(async move {
                match crate::aws::services::waf::fetch_sampled_requests(
                    client, arn, name.clone(), id, scope,
                )
                .await
                {
                    Ok(content) => {
                        let _ = tx.send(crate::event::Event::WafSampledRequestsLoaded {
                            content});
                    }
                    Err(e) => {
                        let _ = tx.send(crate::event::Event::ResourceLoadError {
                            service: crate::aws::service::ServiceType::Waf,
                            error: format!("Failed to fetch sampled requests: {}", e)});
                    }
                }
            });
            return true;
        }
        false
    }

