    /// Fetch the selected dashboard's body plus every time-series it charts.
    /// Unlike the other `m` triggers this reports its failure (the state has an
    /// `Error` arm) — a denied `GetDashboard` would otherwise spin forever.
    fn trigger_cw_dashboard_metrics_load(&mut self, event_tx: &mpsc::UnboundedSender<Event>) {
        if let Some(d) = self.get_selected_resource().and_then(|r| {
            r.as_any()
                .downcast_ref::<crate::aws::services::cloudwatch::CwDashboard>()
        }) {
            let name = d.name.clone();
            let time_range = self.cw_dashboard_metrics_time_range;
            let honor_body_range = self.cw_dashboard_range_from_body;
            let region = self.current_region.as_str().to_string();
            self.cw_dashboard_metrics.insert(
                name.clone(),
                crate::aws::services::cloudwatch::CwDashboardMetricsState::Loading,
            );
            // The whole config, not one client: a widget can pin its own region
            // and we only learn which after the body comes back.
            let config = self.aws_clients.sdk_config().clone();
            let tx = event_tx.clone();
            tokio::spawn(async move {
                match crate::aws::services::cloudwatch::fetch_dashboard_metrics(
                    config,
                    name.clone(),
                    region,
                    time_range,
                    honor_body_range,
                )
                .await
                {
                    Ok(data) => {
                        let _ = tx.send(crate::event::Event::CwDashboardMetricsLoaded {
                            name,
                            data: Box::new(data),
                        });
                    }
                    Err(e) => {
                        let _ = tx.send(crate::event::Event::CwDashboardMetricsFailed {
                            name,
                            error: format!("{}", e),
                        });
                    }
                }
            });
        }
    }

    /// Mouse on the charted dashboard: click a widget to put the cursor on it,
    /// double-click to zoom (and again to come back), wheel to scroll the grid.
    /// Returns whether the event was consumed.
    ///
    /// Clicking beats `Tab` on any dashboard bigger than a handful of widgets,
    /// which is most of them.
    fn handle_cw_dashboard_mouse(&mut self, mouse: MouseEvent) -> bool {
        match mouse.kind {
            MouseEventKind::ScrollDown if !self.cw_dashboard_zoomed => {
                let max = self.cw_dashboard_grid_rows();
                self.cw_dashboard_scroll = (self.cw_dashboard_scroll + 2).min(max);
                true
            }
            MouseEventKind::ScrollUp if !self.cw_dashboard_zoomed => {
                self.cw_dashboard_scroll = self.cw_dashboard_scroll.saturating_sub(2);
                true
            }
            MouseEventKind::Down(MouseButton::Left) => {
                let (col, row) = (mouse.column, mouse.row);
                let hit = self
                    .cw_dashboard_regions
                    .borrow()
                    .iter()
                    .find(|(_, r)| point_in(*r, col, row))
                    .map(|(i, _)| *i);
                let Some(idx) = hit else { return false };

                // Same double-click window as everywhere else, and it shares
                // `last_left_click` so a double never straddles two widgets.
                const DOUBLE_CLICK_MS: u128 = 400;
                let now = std::time::Instant::now();
                let double = self.last_left_click.is_some_and(|(t, c, r)| {
                    c == col && r == row && now.duration_since(t).as_millis() < DOUBLE_CLICK_MS
                });
                self.last_left_click = if double { None } else { Some((now, col, row)) };

                self.cw_dashboard_cursor = Some(idx);
                if double {
                    self.cw_dashboard_zoomed = !self.cw_dashboard_zoomed;
                }
                true
            }
            _ => false,
        }
    }

    /// Move the widget cursor to the next (or previous) **selectable** widget.
    /// Text panels are skipped: there is nothing to zoom into, and stopping on
    /// one would make `Tab` feel like it had missed.
    fn cw_dashboard_step_cursor(&mut self, back: bool) {
        let selectable = self.cw_dashboard_selectable();
        if selectable.is_empty() {
            return;
        }
        let next = match self.cw_dashboard_cursor.and_then(|c| {
            selectable.iter().position(|i| *i == c)
        }) {
            Some(pos) if back => (pos + selectable.len() - 1) % selectable.len(),
            Some(pos) => (pos + 1) % selectable.len(),
            None if back => selectable.len() - 1,
            None => 0,
        };
        self.cw_dashboard_cursor = Some(selectable[next]);
    }

    /// Indices of the widgets `Tab` visits.
    pub(crate) fn cw_dashboard_selectable(&self) -> Vec<usize> {
        use crate::aws::services::cloudwatch::CwDashboardMetricsState;
        let name = match self
            .get_selected_resource()
            .and_then(|r| {
                r.as_any()
                    .downcast_ref::<crate::aws::services::cloudwatch::CwDashboard>()
            })
            .map(|d| d.name.clone())
        {
            Some(n) => n,
            None => return Vec::new(),
        };
        match self.cw_dashboard_metrics.get(&name) {
            Some(CwDashboardMetricsState::Loaded(d)) => d
                .widgets
                .iter()
                .enumerate()
                .filter(|(_, w)| w.kind != "text")
                .map(|(i, _)| i)
                .collect(),
            _ => Vec::new(),
        }
    }

    /// Total scrollable height of the charted dashboard grid, in terminal rows
    /// (the renderer clamps to the viewport; this just stops `j` running away).
    fn cw_dashboard_grid_rows(&self) -> u16 {
        use crate::aws::services::cloudwatch::CwDashboardMetricsState;
        let name = match self
            .get_selected_resource()
            .and_then(|r| {
                r.as_any()
                    .downcast_ref::<crate::aws::services::cloudwatch::CwDashboard>()
            })
            .map(|d| d.name.clone())
        {
            Some(n) => n,
            None => return 0,
        };
        match self.cw_dashboard_metrics.get(&name) {
            Some(CwDashboardMetricsState::Loaded(d)) => {
                crate::ui::widgets::metrics_overlay::dashboard_grid_rows(&d.widgets)
            }
            _ => 0,
        }
    }

